INSERT INTO `faq` (`id`, `topic_group`, `tu_khoa`, `noi_dung`, `variations`, `link_dieu_huong`) VALUES
(1, 'Thông tin chung', 'Địa chỉ trường ở đâu? UTH có mấy cơ sở? Trường nằm ở chỗ nào?', 'Trường Đại học Giao thông Vận tải TP.HCM (UTH) có cơ sở chính tại Số 2, Đường Võ Oanh, Phường 25, Quận Bình Thạnh, TP.HCM. Ngoài ra, trường còn có các cơ sở đào tạo khác tại Quận 12 (TP.HCM), TP. Thủ Đức và TP. Vũng Tàu.', 'địa chỉ trường ở đâu, uth có mấy cơ sở, trường nằm ở chỗ nào, thông tin chung, thông tin chung là sao', '/thong-tin-truong'),
(2, 'Chương trình Đào tạo', 'Trường có những ngành gì? Ngành CNTT học hệ nào? Đào tạo chất lượng cao là sao?', 'UTH là trường công lập đào tạo đa ngành hàng đầu về Giao thông vận tải, Logistics, Công nghệ thông tin, Khoa học dữ liệu, Điện tử viễn thông, Kinh tế vận tải và Kỹ thuật công trình. Hệ đào tạo gồm 2 loại hình: Hệ Đại trà và Hệ Chất lượng cao.', 'trường có những ngành gì, ngành cntt học hệ nào, đào tạo chất lượng cao là sao, chương trình đào tạo, chương trình đào tạo là sao', '/chuong-trinh-khung'),
(3, 'Cách Tính Điểm', 'Cách tính điểm môn học thế nào? Điểm F là gì? Quy chế thang điểm chữ?', 'UTH áp dụng đào tạo theo hệ thống tín chỉ. Điểm tổng kết môn gồm: Điểm quá trình và Điểm thi kết thúc học phần. Điểm tính theo thang điểm 10 rồi quy đổi sang thang điểm chữ (A, B, C, D, F) tương ứng với thang điểm 4. Điểm F là rớt môn và bắt buộc phải đóng tiền đăng ký học lại.', 'cách tính điểm môn học thế nào, điểm f là gì, quy chế thang điểm chữ, cách tính điểm, cách tính điểm là sao, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm', '/ket-qua-hoc-tap'),
(4, 'Học Cải Thiện', 'Điểm thấp có được học lại không? Làm sao để nâng điểm tích lũy?', 'Sinh viên đạt điểm trung bình môn ở mức D, D+, C, C+ muốn nâng cao điểm trung bình tích lũy (GPA) được phép đăng ký học cải thiện vào các học kỳ tiếp theo. Khi học cải thiện, điểm của lần học sau sẽ thay thế hoàn toàn cho điểm của lần học trước.', 'điểm thấp có được học lại không, làm sao để nâng điểm tích lũy, học cải thiện, học cải thiện là sao, đkhp, dkmh, đk môn, add môn, hủy môn, rút môn', '/ket-qua-hoc-tap'),
(5, 'Cảnh Báo Học Vụ', 'Điều kiện xét nâng lớp? Khi nào bị cảnh báo học vụ? Bị buộc thôi học khi nào?', 'Sinh viên sẽ bị cảnh báo học vụ nếu điểm trung bình tích lũy học kỳ đạt dưới 0.8 (đối với học kỳ đầu tiên) hoặc dưới 1.0 (đối với các học kỳ tiếp theo), hoặc số tín chỉ bị nợ vượt quá quy định. Bị cảnh báo học vụ 2 lần liên tiếp sẽ thuộc diện xem xét buộc thôi học.', 'điều kiện xét nâng lớp, khi nào bị cảnh báo học vụ, bị buộc thôi học khi nào, cảnh báo học vụ, cảnh báo học vụ là sao', '/thong-tin-ca-nhan'),
(6, 'Đăng Ký Môn Học', 'Khi nào đăng ký học phần? Một kỳ được đăng ký tối đa bao nhiêu tín chỉ? Hủy môn học ở đâu?', 'Sinh viên thực hiện đăng ký học phần (DKMH) trực tuyến tại trang Portal UTH theo khung thời gian thông báo của Phòng Đào tạo. Sinh viên hệ đại trà được đăng ký tối đa 24 tín chỉ và tối thiểu 14 tín chỉ trong một học kỳ chính.', 'khi nào đăng ký học phần, một kỳ được đăng ký tối đa bao nhiêu tín chỉ, hủy môn học ở đâu, đăng ký môn học, đăng ký môn học là sao, đkhp, dkmh, đk môn, add môn, hủy môn, rút môn', '/dang-ky-hoc-phan'),
(7, 'Môn Điều Kiện', 'Môn tiên quyết là gì? Môn học trước là gì? Khác nhau thế nào?', 'Môn tiên quyết là môn sinh viên bắt buộc phải học và thi đạt (điểm chữ từ D trở lên) mới được đăng ký môn tiếp theo. Môn học trước là môn sinh viên chỉ cần hoàn thành khóa học (kể cả thi rớt điểm F) là đã đủ điều kiện đăng ký môn sau.', 'môn tiên quyết là gì, môn học trước là gì, khác nhau thế nào, môn điều kiện, môn điều kiện là sao, đkhp, dkmh, đk môn, add môn, hủy môn, rút môn', '/dang-ky-mon-hoc-dieu-kien'),
(8, 'Quy Chế Thi Cử', 'Xem lịch thi ở đâu? Vào phòng thi cần mang gì? Hoãn thi làm sao?', 'Lịch thi học kỳ được công bố trên Portal trước kỳ thi 2 tuần. Khi vào phòng thi, sinh viên bắt buộc phải xuất trình Thẻ sinh viên chính thức hoặc giấy tờ tùy thân có ảnh (CCCD). Sinh viên vắng thi không có lý do chính đáng sẽ nhận điểm 0.', 'xem lịch thi ở đâu, vào phòng thi cần mang gì, hoãn thi làm sao, quy chế thi cử, quy chế thi cử là sao, lịch thi, hoãn thi, vắng thi, đi thi cần gì', '/lich-hoc-trong-tuan'),
(9, 'Học phí theo tín chỉ khóa 2025', 'học phí khóa 2025, học phí 2025, hoc phi 2025, học phí đại trà 2025, học phí chương trình tiên tiến 2025', 'Với khóa 2025 trong dữ liệu hiện có, học phí UTH được tính theo số tín chỉ đăng ký: chương trình chuẩn (đại trà) 400.000đ/tín chỉ; chương trình tiên tiến (trước đây gọi là Chất lượng cao) 980.000đ/tín chỉ. Tổng học phí học kỳ = đơn giá tín chỉ x số tín chỉ đăng ký.', 'học phí khóa 2025, học phí 2025, học phí đại trà 2025, học phí chương trình tiên tiến 2025, học phí theo tín chỉ khóa 2025, học phí theo tín chỉ khóa 2025 là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, hp 2025, học phí 1 chỉ 2025, đại trà bao nhiêu 1 tín, clc 2025 bao nhiêu', '/cong-thanh-toan'),
(146, 'Học phí theo tín chỉ khóa 2026', 'học phí khóa 2026, học phí tân sinh viên 2026, học phí chương trình chuẩn 2026, học phí chương trình tiên tiến 2026, học phí chương trình tiếng Anh 2026', 'Với tân sinh viên khóa 2026, học phí dự kiến theo tín chỉ gồm: chương trình chuẩn 515.000đ/tín chỉ; chương trình tiên tiến 1.120.000đ/tín chỉ; chương trình hoàn toàn bằng tiếng Anh 1.500.000đ/tín chỉ. Tổng tiền từng học kỳ phụ thuộc số tín chỉ sinh viên đăng ký.', 'học phí khóa 2026, học phí tân sinh viên 2026, học phí chương trình chuẩn 2026, học phí chương trình tiên tiến 2026, học phí chương trình tiếng anh 2026, học phí theo tín chỉ khóa 2026, học phí theo tín chỉ khóa 2026 là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, hp k26, k26 đóng bao nhiêu, học phí tân sinh viên, tiên tiến 2026 bao nhiêu, tiếng anh 1 tín bao nhiêu', '/cong-thanh-toan'),
(147, 'Cách đóng và tra cứu học phí', 'đóng học phí ở đâu, tra cứu học phí, cổng thanh toán học phí, payment UTH, xem công nợ học phí', 'Sinh viên nộp học phí trực tuyến qua Cổng thanh toán của trường tại payment.ut.edu.vn. Số tiền cần đóng nên được tra cứu trực tiếp trên Portal cá nhân hoặc mục công nợ để tránh nhầm học phí giữa các chương trình và số tín chỉ đã đăng ký.', 'đóng học phí ở đâu, tra cứu học phí, cổng thanh toán học phí, payment uth, xem công nợ học phí, cách đóng và tra cứu học phí, cách đóng và tra cứu học phí là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, payment, coi công nợ, nộp hp, thanh toán học phí, portal báo bao nhiêu', '/cong-thanh-toan'),
(148, 'Cam kết không tăng học phí', 'cam kết không tăng học phí, học phí có tăng không, học phí ổn định mấy năm, học phí khóa học có bị tăng không', 'Trường cam kết không tăng học phí trong 3 năm đầu tính từ năm nhập học của mỗi khóa. Sau thời gian cam kết, sinh viên cần theo dõi thông báo học phí chính thức từng năm học trên Portal hoặc website trường.', 'cam kết không tăng học phí, học phí có tăng không, học phí ổn định mấy năm, học phí khóa học có bị tăng không, cam kết không tăng học phí là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, tiền học có bị đội lên không, 3 năm đầu có tăng hp không, cam kết hp', '/cong-thanh-toan'),
(10, 'Gia Hạn Học Phí', 'Không có tiền đóng học phí làm sao? Xin nợ học phí ở đâu?', 'Sinh viên có hoàn cảnh khó khăn không thể hoàn thành học phí đúng hạn phải làm Đơn xin gia hạn học phí trực tuyến gửi Phòng Công tác sinh viên trước thời hạn quy định để không bị khóa tài khoản đăng ký môn học và bị cấm thi.', 'không có tiền đóng học phí làm sao, xin nợ học phí ở đâu, gia hạn học phí, gia hạn học phí là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu', '/tra-cuu-cong-no'),
(11, 'Hoạt Động Đoàn Hội', 'Lịch hiến máu tình nguyện? Tham gia hoạt động được cộng bao nhiêu điểm rèn luyện?', 'Ngày hội hiến máu tình nguyện trường UTH được tổ chức định kỳ hàng năm tại Sảnh lớn khu giảng đường A. Sinh viên tham gia hiến máu nhân đạo sẽ được cấp giấy chứng nhận, hỗ trợ chi phí và được cộng 5 điểm rèn luyện (ĐRL) vào mục hoạt động cộng đồng.', 'lịch hiến máu tình nguyện, tham gia hoạt động được cộng bao nhiêu điểm rèn luyện, hoạt động đoàn hội, hoạt động đoàn hội là sao, đrl, điểm rl, chấm drl, cộng điểm rl, khiếu nại drl, hiến máu, cộng điểm hiến máu, nghỉ học hiến máu', '/thong-bao-su-kien'),
(12, 'Các Câu Lạc Bộ', 'Trường có CLB guitar không? Đội tình nguyện hoạt động thế nào?', 'UTH hiện có hơn 20 Câu lạc bộ (CLB) sinh viên đang hoạt động thuộc các khối: Học thuật (CLB Tin học, CLB Logistics), Nghệ thuật (CLB Guitar, CLB Bước Nhảy), Thể thao (CLB Bóng đá, Bóng chuyền) và Tình nguyện (Đội Công tác xã hội, CLB Tiếp sức đến trường).', 'trường có clb guitar không, đội tình nguyện hoạt động thế nào, các câu lạc bộ, các câu lạc bộ là sao', '/thong-bao-su-kien'),
(13, 'Học Bổng Khuyến Khích', 'Điều kiện nhận học bổng trường? Điểm rèn luyện bao nhiêu thì được học bổng?', 'Học bổng khuyến khích học tập UTH được xét sau mỗi học kỳ dựa trên 2 tiêu chí song song: Điểm trung bình học tập đạt loại Khá trở lên (từ 2.5/4.0) và Điểm rèn luyện đạt loại Tốt trở lên (từ 80 điểm/100), đồng thời không bị kỷ luật và không nợ môn.', 'điều kiện nhận học bổng trường, điểm rèn luyện bao nhiêu thì được học bổng, học bổng khuyến khích, học bổng khuyến khích là sao, đrl, điểm rl, chấm drl, cộng điểm rl, khiếu nại drl, hb, xin học bổng, săn hb, được học bổng không', '/thong-bao-su-kien'),
(14, 'Chuẩn Đầu Ra Ngoại Ngữ', 'Chuẩn tiếng Anh xét tốt nghiệp? Nộp bằng TOEIC ở đâu? Điều kiện miễn học Anh văn?', 'Sinh viên đại học chính quy UTH phải đạt chuẩn đầu ra tiếng Anh theo quy định (thường là TOEIC 450 trở lên hoặc B1 VSTEP tùy theo ngành học). Chứng chỉ phải còn giá trị hiệu lực và nộp về Trung tâm Ngoại ngữ trường để làm thủ tục hậu kiểm xét tốt nghiệp.', 'chuẩn tiếng anh xét tốt nghiệp, nộp bằng toeic ở đâu, điều kiện miễn học anh văn, chuẩn đầu ra ngoại ngữ, chuẩn đầu ra ngoại ngữ là sao, ielts, toeic, chuẩn anh, miễn anh văn, nộp bằng anh, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/dich-vu-sinh-vien'),
(15, 'Chuẩn Tin Học', 'Chuẩn tin học đầu ra là gì? Chứng chỉ MOS hay IC3?', 'Sinh viên UTH bắt buộc phải hoàn thành chuẩn đầu ra Tin học bằng việc đạt chứng chỉ Tin học đại chúng đại học hoặc các chứng chỉ quốc tế được công nhận tương đương như MOS (đạt 3 kỹ năng Word, Excel, Powerpoint) hoặc IC3.', 'chuẩn tin học đầu ra là gì, chứng chỉ mos hay ic3, chuẩn tin học, chuẩn tin học là sao, mos, ic3, tin học đầu ra', '/dich-vu-sinh-vien'),
(16, 'Điều Kiện Tốt Nghiệp', 'Làm sao để được ra trường? Điều kiện xét tốt nghiệp UTH? Nợ môn có được xét tốt nghiệp?', 'Điều kiện xét công nhận tốt nghiệp UTH: Tích lũy đủ số tín chỉ của chương trình khung; Điểm trung bình tích lũy (GPA) toàn khóa đạt từ 2.0/4.0 trở lên; Đạt chuẩn đầu ra Ngoại ngữ và Tin học; Đạt chứng chỉ Giáo dục quốc phòng và Giáo dục thể chất; Không trong thời gian bị kỷ luật.', 'làm sao để được ra trường, điều kiện xét tốt nghiệp uth, nợ môn có được xét tốt nghiệp, điều kiện tốt nghiệp, điều kiện tốt nghiệp là sao, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/chuong-trinh-khung'),
(17, 'Mất Thẻ Sinh Viên', 'Làm lại thẻ sinh viên ở đâu? Mất thẻ sinh viên đóng phạt bao nhiêu?', 'Khi bị mất thẻ, sinh viên đến Phòng Công tác sinh viên (Cơ sở chính, khu nhà A) để làm thủ tục xin cấp lại thẻ sinh viên mới. Lệ phí cấp lại thẻ theo quy định là 50.000đ. Trong thời gian chờ cấp thẻ mới, sinh viên được cấp giấy xác nhận tạm thời để ra vào trường.', 'làm lại thẻ sinh viên ở đâu, mất thẻ sinh viên đóng phạt bao nhiêu, mất thẻ sinh viên, mất thẻ sinh viên là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/dich-vu-sinh-vien'),
(18, 'Ký Túc Xá Trường', 'Đăng ký ở KTX ở đâu? Chi phí Ký túc xá UTH? Đối tượng ưu tiên ở KTX?', 'UTH hỗ trợ chỗ ở tại Ký túc xá trường cho sinh viên (ưu tiên sinh viên diện chính sách, vùng sâu vùng xa, hoàn cảnh khó khăn). Sinh viên làm Đơn đăng ký nội trú trực tuyến trên Portal hoặc nộp hồ sơ trực tiếp tại Ban quản lý Ký túc xá trong thời gian quy định đầu năm học.', 'đăng ký ở ktx ở đâu, chi phí ký túc xá uth, đối tượng ưu tiên ở ktx, ký túc xá trường, ký túc xá trường là sao, ktx, ở ktx, phòng ktx, nội trú, ký túc xá', '/thong-bao-su-kien'),
(19, 'Mượn Sách Thư Viện', 'Thư viện trường ở đâu? Cách mượn sách về nhà? Trả sách trễ hạn bị phạt thế nào?', 'Thư viện UTH đặt tại khu vực cơ sở chính. Sinh viên sử dụng Thẻ sinh viên để vào thư viện đọc sách hoặc làm thủ tục mượn tài liệu về nhà. Thời gian mượn tối đa là 2 tuần/cuốn. Nếu trả sách trễ hạn, sinh viên sẽ bị phạt tiền theo quy định của thư viện.', 'thư viện trường ở đâu, cách mượn sách về nhà, trả sách trễ hạn bị phạt thế nào, mượn sách thư viện, mượn sách thư viện là sao', '/dich-vu-sinh-vien'),
(20, 'Bảo Hiểm Y Tế', 'Đóng tiền bảo hiểm y tế ở đâu? Hạn chót nộp BHYT? Gia hạn bảo hiểm sinh viên?', 'Bảo hiểm y tế (BHYT) là hình thức bắt buộc đối với tất cả sinh viên. Nhà trường tổ chức thu tiền và gia hạn BHYT định kỳ vào đầu năm học thông qua Cổng thanh toán trực tuyến. Sinh viên có thẻ BHYT diện hộ nghèo, thân nhân quân nhân phải nộp bản photo minh chứng để được miễn giảm.', 'đóng tiền bảo hiểm y tế ở đâu, hạn chót nộp bhyt, gia hạn bảo hiểm sinh viên, bảo hiểm y tế, bảo hiểm y tế là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, bhyt, vssid, bảo hiểm sv, gia hạn bhyt', '/cong-thanh-toan'),
(21, 'Sinh Viên 5 Tốt', 'Tiêu chí đạt Sinh viên 5 Tốt? Quyền lợi khi đạt Sinh viên 5 Tốt UTH?', 'Danh hiệu Sinh viên 5 Tốt được xét duyệt hàng năm dựa trên 5 tiêu chí: Học tập tốt (GPA >= 3.2 hoặc 2.8 tùy hệ), Đạo đức tốt (ĐRL >= 80), Thể lực tốt (đạt danh hiệu khỏe), Tình nguyện tốt (tham gia chiến dịch lớn), và Hội nhập tốt (đạt giải thưởng khoa học hoặc kỹ năng ngoại ngữ tốt).', 'tiêu chí đạt sinh viên 5 tốt, quyền lợi khi đạt sinh viên 5 tốt uth, sinh viên 5 tốt, sinh viên 5 tốt là sao', '/thong-bao-su-kien'),
(22, 'Nghiên Cứu Khoa Học', 'Đăng ký nghiên cứu khoa học ở đâu? Quyền lợi khi làm NCKH sinh viên?', 'Phong trào Nghiên cứu khoa học (NCKH) sinh viên UTH được phát động vào đầu học kỳ 1. Sinh viên đăng ký đề tài theo nhóm (dưới sự hướng dẫn của giảng viên) thông qua Phòng Quản lý khoa học. Đề tài nghiệm thu đạt loại Khá trở lên sẽ được cộng điểm rèn luyện và thưởng tiền mặt.', 'đăng ký nghiên cứu khoa học ở đâu, quyền lợi khi làm nckh sinh viên, nghiên cứu khoa học, nghiên cứu khoa học là sao', '/thong-bao-su-kien'),
(23, 'Rút Học Phần, Hủy Môn', 'Cách rút môn học? Hạn chót hủy học phần đã đăng ký? Rút môn có được hoàn tiền không?', 'Trong 2 tuần đầu của học kỳ chính (hoặc 1 tuần đối với học kỳ hè), sinh viên được phép nộp đơn online để xin rút bớt học phần đã đăng ký. Học phần xin rút thành công sẽ ghi nhận điểm chữ W trên bảng điểm, không tính vào điểm trung bình tích lũy nhưng sinh viên không được hoàn lại học phí.', 'cách rút môn học, hạn chót hủy học phần đã đăng ký, rút môn có được hoàn tiền không, rút học phần, hủy môn, rút học phần, hủy môn là sao, đkhp, dkmh, đk môn, add môn, hủy môn, rút môn', '/dang-ky-hoc-phan'),
(24, 'Phòng Công Tác Sinh Viên', 'Liên hệ phòng CTSV ở đâu? Xin giấy xác nhận sinh viên vay vốn ở đâu?', 'Phòng Công tác sinh viên (CTSV) chịu trách nhiệm giải quyết các thủ tục: Cấp giấy xác nhận sinh viên để vay vốn ngân hàng, tạm hoãn nghĩa vụ quân sự, đánh giá điểm rèn luyện, giải quyết chế độ chính sách, miễn giảm học phí. Văn phòng đặt tại tầng trệt nhà A cơ sở chính.', 'liên hệ phòng ctsv ở đâu, xin giấy xác nhận sinh viên vay vốn ở đâu, phòng công tác sinh viên, phòng công tác sinh viên là sao', '/dich-vu-sinh-vien'),
(25, 'Phòng Đào Tạo', 'Số điện thoại Phòng Đào tạo? Hỏi về lịch học, lịch thi, xét tốt nghiệp ở đâu?', 'Phòng Đào tạo UTH là nơi giải quyết các vấn đề chuyên môn về: Khung lịch học, lịch thi, giải quyết đơn phúc khảo điểm thi, cấp bảng điểm chính thức, xử lý hồ sơ chuyển ngành, ngừng học tạm thời, bảo lưu kết quả, và xét công nhận tốt nghiệp.', 'số điện thoại phòng đào tạo, hỏi về lịch học, lịch thi, xét tốt nghiệp ở đâu, phòng đào tạo, phòng đào tạo là sao, hoãn thi, vắng thi, đi thi cần gì, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/thong-tin-truong'),
(26, 'Ký Túc Xá Quận 12', 'KTX Quận 12 ở đâu? Đăng ký ký túc xá cơ sở 2? Chi phí phòng KTX Quận 12?', 'Cơ sở 2 của UTH tại Quận 12 có khu Ký túc xá khang trang dành riêng cho sinh viên học tập tại đây. Chi phí nội trú dao động từ 150.000đ - 250.000đ/tháng/sinh viên tùy loại phòng. Sinh viên nộp đơn đăng ký trực tiếp tại Ban quản lý KTX Cơ sở 2.', 'ktx quận 12 ở đâu, đăng ký ký túc xá cơ sở 2, chi phí phòng ktx quận 12, ký túc xá quận 12, ký túc xá quận 12 là sao, ktx, ở ktx, phòng ktx, nội trú, ký túc xá', '/thong-bao-su-kien'),
(27, 'Học Bổng Doanh Nghiệp', 'Học bổng tài trợ? Điều kiện nhận học bổng ngoài ngân sách? Học bổng vượt khó?', 'Ngoài học bổng khuyến khích của trường, sinh viên UTH còn có cơ hội nhận Học bổng tài trợ từ các tập đoàn, doanh nghiệp lớn đối tác (như các tổng công ty xây dựng, cảng biển, công ty công nghệ). Tiêu chí xét tuyển thường ưu tiên sinh viên nghèo vượt khó học giỏi hoặc có thành tích xuất sắc.', 'học bổng tài trợ, điều kiện nhận học bổng ngoài ngân sách, học bổng vượt khó, học bổng doanh nghiệp, học bổng doanh nghiệp là sao, hb, xin học bổng, săn hb, được học bổng không', '/thong-bao-su-kien'),
(28, 'Các Tuyến Xe Buýt', 'Xe buýt nào đi qua trường UTH? Đi xe bus đến Võ Oanh? Xe bus qua cơ sở Bình Thạnh?', 'Cơ sở chính Võ Oanh (Bình Thạnh) có rất nhiều tuyến xe buýt đi qua như tuyến số 08, 14, 19, 43, 44, 93 (dừng tại trạm Điện Biên Phủ hoặc Nguyễn Văn Thương rồi đi bộ vào). Sinh viên được hưởng giá vé ưu đãi khi xuất trình Thẻ sinh viên UTH.', 'xe buýt nào đi qua trường uth, đi xe bus đến võ oanh, xe bus qua cơ sở bình thạnh, các tuyến xe buýt, các tuyến xe buýt là sao', '/thong-tin-truong'),
(29, 'Thủ Tục Chuyển Ngành', 'Làm sao để đổi ngành học? Điều kiện chuyển ngành UTH? Đang học có được đổi ngành khác?', 'Sinh viên được xem xét chuyển ngành nếu: Không thuộc diện bị buộc thôi học; Điểm xét tuyển đầu vào không thấp hơn điểm trúng tuyển của ngành muốn chuyển sang; Có đơn xin chuyển ngành và được sự đồng ý của cả hai Khoa chủ quản. Thủ tục làm tại Phòng Đào tạo vào cuối năm học thứ nhất.', 'làm sao để đổi ngành học, điều kiện chuyển ngành uth, đang học có được đổi ngành khác, thủ tục chuyển ngành, thủ tục chuyển ngành là sao', '/dich-vu-sinh-vien'),
(30, 'Bảo Lưu Kết Quả', 'Xin tạm dừng học? Cách làm đơn bảo lưu học tập? Nghỉ học tạm thời được bao lâu?', 'Sinh viên được xin nghỉ học tạm thời và bảo lưu kết quả học tập vì lý do cá nhân (như sức khỏe, hoàn cảnh gia đình hoặc thực hiện nghĩa vụ quân sự). Thời gian tạm dừng học không quá 2 học kỳ chính và phải làm đơn nộp về Phòng Đào tạo trước khi học kỳ mới bắt đầu.', 'xin tạm dừng học, cách làm đơn bảo lưu học tập, nghỉ học tạm thời được bao lâu, bảo lưu kết quả, bảo lưu kết quả là sao', '/dich-vu-sinh-vien'),
(31, 'Phúc Khảo Điểm Thi', 'Chấm phúc khảo ở đâu? Lệ phí phúc khảo bài thi? Thời hạn nộp đơn chấm phúc khảo?', 'Nếu thấy điểm thi kết thúc học phần không chính xác, sinh viên có quyền làm Đơn xin phúc khảo bài thi nộp về Phòng Đào tạo hoặc văn phòng Khoa trong vòng 5 ngày làm việc kể từ ngày công bố điểm. Lệ phí phúc khảo theo quy định hiện hành của trường.', 'chấm phúc khảo ở đâu, lệ phí phúc khảo bài thi, thời hạn nộp đơn chấm phúc khảo, phúc khảo điểm thi, phúc khảo điểm thi là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm', '/ket-qua-hoc-tap'),
(32, 'Đồng Phục & Trang Phục', 'Quy định đồng phục UTH? Mặc áo gì đi học? Có bắt buộc mặc áo trường không?', 'Sinh viên khi đến trường UTH phải ăn mặc lịch sự, gọn gàng, không mặc quần đùi, áo ba lỗ, dép lê vào lớp. Nhà trường khuyến khích sinh viên mặc Áo thun đồng phục UTH hoặc áo sơ mi trắng vào các ngày lễ, các buổi sinh hoạt chung và các ngày cố định theo quy định của Khoa.', 'quy định đồng phục uth, mặc áo gì đi học, có bắt buộc mặc áo trường không, đồng phục & trang phục, đồng phục & trang phục là sao', '/thong-bao-su-kien'),
(33, 'Kỷ Luật Học Đường', 'Quy chế kỷ luật sinh viên? Đi thi gian lận bị phạt thế nào? Quay cóp bài thi bị xử lý sao?', 'Sinh viên vi phạm quy chế thi cử (như mang tài liệu, điện thoại vào phòng thi, quay cóp) sẽ bị xử lý kỷ luật nghiêm khắc từ Đình chỉ thi môn đó, Nhận điểm 0, Cảnh cáo trước toàn trường, cho đến đình chỉ học tập có thời hạn hoặc buộc thôi học nếu tái phạm nhiều lần.', 'quy chế kỷ luật sinh viên, đi thi gian lận bị phạt thế nào, quay cóp bài thi bị xử lý sao, kỷ luật học đường, kỷ luật học đường là sao', '/thong-tin-ca-nhan'),
(34, 'Văn Phòng Khoa CNTT', 'Liên hệ khoa CNTT ở đâu? Số điện thoại khoa Công nghệ thông tin UTH?', 'Văn phòng Khoa Công nghệ thông tin UTH chịu trách nhiệm quản lý chuyên môn ngành CNTT và Khoa học dữ liệu. Văn phòng khoa hỗ trợ sinh viên các vấn đề về: Đăng ký đồ án tốt nghiệp, thực tập doanh nghiệp, cố vấn học tập. Địa chỉ liên hệ đặt tại Khu nhà C, Cơ sở chính.', 'liên hệ khoa cntt ở đâu, số điện thoại khoa công nghệ thông tin uth, văn phòng khoa cntt, văn phòng khoa cntt là sao', '/thong-tin-truong'),
(35, 'Văn Phòng Khoa Viện', 'Liên hệ Viện Logistics ở đâu? Văn phòng Khoa Kinh tế vận tải nằm ở đâu?', 'Các văn phòng Khoa chuyên ngành (như Viện Logistics và Quản lý chuỗi cung ứng, Khoa Kinh tế vận tải, Khoa Công trình giao thông, Khoa Điện - Điện tử viễn thông) đều có văn phòng trực ban tại các khu nhà chức năng cơ sở chính để hỗ trợ giải quyết lịch học chuyên ngành cho sinh viên.', 'liên hệ viện logistics ở đâu, văn phòng khoa kinh tế vận tải nằm ở đâu, văn phòng khoa viện, văn phòng khoa viện là sao', '/thong-tin-truong'),
(36, 'Giáo Dục Quốc Phòng', 'Học quân sự ở đâu? Lịch học giáo dục quốc phòng? Đi học quân sự cần chuẩn bị gì?', 'Sinh viên UTH tham gia học môn Giáo dục quốc phòng - An ninh tập trung tại Trung tâm Giáo dục Quốc phòng theo lịch phân bổ của trường. Sinh viên được rèn luyện trong môi trường quân đội nội trú, phải tuân thủ nghiêm ngặt giờ giấc, tác phong quân kỷ và mặc quân phục.', 'học quân sự ở đâu, lịch học giáo dục quốc phòng, đi học quân sự cần chuẩn bị gì, giáo dục quốc phòng, giáo dục quốc phòng là sao', '/thong-bao-su-kien'),
(37, 'Giáo Dục Thể Chất', 'Học thể dục ở đâu? Các môn thể dục UTH? Đăng ký học môn thể thao nào?', 'Môn Giáo dục thể chất (Thể dục) tại UTH rất đa dạng, sinh viên được tự chọn đăng ký các môn thể thao yêu thích trên Portal như: Bóng đá, Bóng chuyền, Bóng rổ, Cầu lông, Cờ vua hoặc Võ thuật. Sinh viên phải thi đạt môn này mới đủ điều kiện xét tốt nghiệp.', 'học thể dục ở đâu, các môn thể dục uth, đăng ký học môn thể thao nào, giáo dục thể chất, giáo dục thể chất là sao', '/dang-ky-hoc-phan'),
(38, 'Cấp Lại Bảng Điểm', 'Xin cấp bảng điểm học tập ở đâu? Lệ phí in bảng điểm chính thức?', 'Sinh viên cần bảng điểm chính thức (có mộc đỏ của trường) để xin việc làm hoặc nộp hồ sơ học bổng phải làm Đơn xin cấp bảng điểm tại máy tự động hoặc nộp trực tiếp tại Phòng Đào tạo. Lệ phí in bảng điểm được tính theo số lượng bản sao quy định.', 'xin cấp bảng điểm học tập ở đâu, lệ phí in bảng điểm chính thức, cấp lại bảng điểm, cấp lại bảng điểm là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm', '/dich-vu-sinh-vien'),
(39, 'Phạt Tiền Thư Viện', 'Làm mất sách thư viện đền tiền thế nào? Quên trả sách thư viện bị phạt bao nhiêu?', 'Sinh viên mượn tài liệu thư viện UTH nếu làm mất hoặc hư hỏng phải mua đền cuốn sách mới tương đương hoặc đền tiền gấp nhiều lần giá trị cuốn sách theo quy chế. Trả sách trễ hạn sẽ bị phạt số tiền tính theo từng ngày trễ hạn và bị tạm khóa thẻ thư viện.', 'làm mất sách thư viện đền tiền thế nào, quên trả sách thư viện bị phạt bao nhiêu, phạt tiền thư viện, phạt tiền thư viện là sao', '/dich-vu-sinh-vien'),
(40, 'Nguyện Vọng Bổ Sung', 'Trường có xét tuyển bổ sung không? Điều kiện xét tuyển đợt 2 UTH?', 'Trong trường hợp các ngành học chưa tuyển đủ chỉ tiêu đợt 1, Hội đồng tuyển sinh UTH sẽ thông báo nhận hồ sơ Xét tuyển nguyện vọng bổ sung (Đợt 2) trên trang tuyển sinh chính thức của trường. Thí sinh nộp hồ sơ theo phương thức xét điểm thi tốt nghiệp THPT hoặc học bạ.', 'trường có xét tuyển bổ sung không, điều kiện xét tuyển đợt 2 uth, nguyện vọng bổ sung, nguyện vọng bổ sung là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không', '/thong-bao-su-kien'),
(41, 'Bảng Điểm Tiếng Anh', 'Xin bảng điểm bằng tiếng Anh ở đâu? Lệ phí dịch thuật bảng điểm UTH? Cấp bảng điểm song ngữ?', 'Sinh viên có nhu cầu cấp bảng điểm bằng tiếng Anh (hoặc song ngữ) để làm hồ sơ du học, săn học bổng quốc tế hoặc nộp cho doanh nghiệp nước ngoài thì làm đơn đăng ký tại Phòng Đào tạo. Thời gian xử lý và cấp phát từ 3 đến 5 ngày làm việc kèm theo lệ phí in ấn quy định.', 'xin bảng điểm bằng tiếng anh ở đâu, lệ phí dịch thuật bảng điểm uth, cấp bảng điểm song ngữ, bảng điểm tiếng anh, bảng điểm tiếng anh là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm', '/dich-vu-sinh-vien'),
(42, 'Phúc Khảo Đồ Án', 'Đồ án tốt nghiệp có được phúc khảo không? Chấm lại điểm khóa luận tốt nghiệp?', 'Theo quy chế học vụ UTH, điểm bảo vệ Đồ án tốt nghiệp hoặc Khóa luận tốt nghiệp sẽ KHÔNG được chấm phúc khảo. Điểm số cuối cùng do Hội đồng chấm tốt nghiệp quyết định ngay tại buổi bảo vệ công khai. Sinh viên chỉ được quyền khiếu nại nếu có sai sót trong quá trình cộng điểm hoặc nhập điểm vào hệ thống.', 'đồ án tốt nghiệp có được phúc khảo không, chấm lại điểm khóa luận tốt nghiệp, phúc khảo đồ án, phúc khảo đồ án là sao, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/ket-qua-hoc-tap'),
(43, 'Khóa Tài Khoản Portal', 'Tại sao tài khoản Portal bị khóa? Lỗi không đăng nhập được trang sinh viên?', 'Tài khoản Portal của sinh viên UTH thường bị khóa vì các lý do sau: Nợ học phí quá hạn quy định; Chưa hoàn thành các khảo sát bắt buộc của trường; Hoặc nhập sai mật khẩu quá 5 lần liên tiếp. Sinh viên cần liên hệ Phòng Đào tạo hoặc Phòng Công tác sinh viên để kiểm tra lý do và mở khóa.', 'tại sao tài khoản portal bị khóa, lỗi không đăng nhập được trang sinh viên, khóa tài khoản portal, khóa tài khoản portal là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/thong-tin-ca-nhan'),
(44, 'Bãi Giữ Xe Của Trường', 'Bãi xe trường ở đâu? Giá vé gửi xe máy UTH? Gửi xe qua đêm tại trường được không?', 'UTH có bãi giữ xe dành cho sinh viên tại tất cả các cơ sở. Giá vé gửi xe máy áp dụng theo đúng quy định nhà nước. Sinh viên tuyệt đối không được gửi xe qua đêm tại trường trừ các trường hợp đặc biệt được Đoàn trường hoặc Ban quản lý cơ sở cấp phép trước bằng văn bản.', 'bãi xe trường ở đâu, giá vé gửi xe máy uth, gửi xe qua đêm tại trường được không, bãi giữ xe của trường, bãi giữ xe của trường là sao', '/thong-tin-truong'),
(45, 'Miễn Giảm Anh Em Ruột', 'Anh em ruột cùng học UTH có được giảm học phí? Chính sách giảm học phí gia đình?', 'Nhà trường áp dụng chính sách hỗ trợ học phí cho gia đình có từ 2 anh/chị/em ruột trở lên đang cùng theo học hệ chính quy tại UTH. Mức giảm thường là 10% đến 20% học phí cho người em. Sinh viên cần nộp Giấy khai sinh bản sao và Đơn đề nghị về Phòng Công tác sinh viên đầu học kỳ.', 'anh em ruột cùng học uth có được giảm học phí, chính sách giảm học phí gia đình, miễn giảm anh em ruột, miễn giảm anh em ruột là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu', '/cong-thanh-toan'),
(46, 'Đổi Lịch Thi Học Kỳ', 'Làm sao để xin đổi ca thi? Bị trùng lịch thi phải làm thế nào? Trùng giờ thi xử lý sao?', 'Trường hợp sinh viên bị trùng lịch thi 2 môn trong cùng 1 ca hoặc có lý do bất khả kháng (tai nạn, nằm viện), sinh viên phải mang minh chứng đến Phòng Đào tạo trước ngày thi ít nhất 3 ngày để làm đơn xin chuyển ca thi hoặc đăng ký thi ghép vào đợt thi của lớp khác.', 'làm sao để xin đổi ca thi, bị trùng lịch thi phải làm thế nào, trùng giờ thi xử lý sao, đổi lịch thi học kỳ, đổi lịch thi học kỳ là sao, lịch thi, hoãn thi, vắng thi, đi thi cần gì', '/lich-hoc-trong-tuan'),
(47, 'Quên Mật Khẩu Portal', 'Làm sao lấy lại mật khẩu Portal? Quên pass trang sinh viên UTH?', 'Nếu quên mật khẩu đăng nhập hệ thống Portal, sinh viên bấm vào nút "Quên mật khẩu" trên giao diện đăng nhập để nhận mã khôi phục qua Email sinh viên (@ut.edu.vn). Nếu không làm được, sinh viên mang Thẻ sinh viên đến trực tiếp Phòng Đào tạo để được cấp lại mật khẩu mới.', 'làm sao lấy lại mật khẩu portal, quên pass trang sinh viên uth, quên mật khẩu portal, quên mật khẩu portal là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/thong-tin-ca-nhan'),
(48, 'Phòng Y Tế Trường', 'Trạm y tế trường nằm ở đâu? Khám sức khỏe sinh viên đầu năm ở đâu?', 'Phòng Y tế UTH nằm tại khu vực tầng trệt cơ sở chính. Đây là nơi tiếp nhận, sơ cứu và cấp phát thuốc cơ bản miễn phí cho sinh viên khi gặp các vấn đề về sức khỏe trong quá trình học tập tại trường. Đồng thời là nơi tổ chức khám sức khỏe định kỳ bắt buộc cho tân sinh viên.', 'trạm y tế trường nằm ở đâu, khám sức khỏe sinh viên đầu năm ở đâu, phòng y tế trường, phòng y tế trường là sao', '/thong-tin-truong'),
(49, 'Học Bổng Liên Kết', 'Học bổng du học UTH? Chương trình trao đổi sinh viên quốc tế?', 'UTH liên kết với nhiều trường Đại học lớn tại Hàn Quốc, Nhật Bản, Hà Lan, Anh Quốc để triển khai các chương trình trao đổi sinh viên và học bổng du học hệ 2+2 hoặc 3+1. Sinh viên có học lực Giỏi và đạt chuẩn tiếng Anh (IELTS/TOEFL) cao sẽ được xét duyệt hồ sơ tham gia.', 'học bổng du học uth, chương trình trao đổi sinh viên quốc tế, học bổng liên kết, học bổng liên kết là sao, hb, xin học bổng, săn hb, được học bổng không', '/thong-bao-su-kien'),
(50, 'Sinh Hoạt Công Dân', 'Tuần sinh hoạt công dân học khi nào? Không học sinh hoạt công dân có bị sao không?', 'Tuần sinh hoạt công dân - học sinh sinh viên được tổ chức bắt buộc vào đầu mỗi năm học. Sinh viên phải tham gia đầy đủ và làm bài kiểm tra thu hoạch đạt yêu cầu. Vắng mặt không lý do sẽ bị trừ điểm rèn luyện nghiêm khắc và xét kỷ luật tùy mức độ.', 'tuần sinh hoạt công dân học khi nào, không học sinh hoạt công dân có bị sao không, sinh hoạt công dân, sinh hoạt công dân là sao', '/thong-bao-su-kien'),
(51, 'Chuyển Cơ Sở Học Tập', 'Sinh viên có được đổi cơ sở học không? Đang học Quận 12 chuyển qua Bình Thạnh?', 'Việc phân bổ cơ sở học tập (Bình Thạnh hoặc Quận 12) phụ thuộc hoàn toàn vào chuyên ngành và kế hoạch đào tạo của từng Khoa/Viện. Sinh viên KHÔNG được tự ý xin chuyển cơ sở học tập cá nhân trừ khi có sự điều chỉnh quy hoạch lớp học từ phía Ban giám hiệu nhà trường.', 'sinh viên có được đổi cơ sở học không, đang học quận 12 chuyển qua bình thạnh, chuyển cơ sở học tập, chuyển cơ sở học tập là sao', '/chuong-trinh-khung'),
(52, 'Mượn Phòng Học', 'Làm sao để mượn phòng học làm hoạt động? Thủ tục mượn hội trường UTH?', 'Các Ban cán sự lớp hoặc Câu lạc bộ muốn mượn phòng học, giảng đường hoặc Hội trường để tổ chức sinh hoạt, họp hành, tập văn nghệ phải làm Đơn xin mượn phòng (có xác nhận của Bí thư Đoàn trường hoặc Trưởng Khoa) nộp về Phòng Quản trị thiết bị trước ít nhất 2 ngày.', 'làm sao để mượn phòng học làm hoạt động, thủ tục mượn hội trường uth, mượn phòng học, mượn phòng học là sao', '/dich-vu-sinh-vien'),
(53, 'Hỗ Trợ Khởi Nghiệp', 'Cuộc thi khởi nghiệp sinh viên UTH? Quỹ hỗ trợ ý tưởng sáng tạo?', 'Nhà trường thường xuyên tổ chức các cuộc thi Ý tưởng khởi nghiệp sáng tạo sinh viên UTH. Các dự án tiềm năng và đạt giải cao sẽ được Câu lạc bộ Khởi nghiệp của trường hỗ trợ không gian làm việc, kết nối với các quỹ đầu tư và cố vấn chuyên môn để phát triển thành dự án thực tế.', 'cuộc thi khởi nghiệp sinh viên uth, quỹ hỗ trợ ý tưởng sáng tạo, hỗ trợ khởi nghiệp, hỗ trợ khởi nghiệp là sao', '/thong-bao-su-kien'),
(54, 'Giấy Chứng Nhận Tạm Thời', 'Xin giấy chứng nhận sinh viên tạm thời ở đâu? Thời gian cấp giấy xác nhận là bao lâu?', 'Để phục vụ các nhu cầu cấp bách (như làm hồ sơ xin việc, chứng minh thông tin khi chưa có thẻ nhựa), sinh viên đăng ký xin cấp Giấy chứng nhận sinh viên tạm thời tại văn phòng Phòng Công tác sinh viên. Giấy xác nhận này có mộc đỏ và giá trị pháp lý ngắn hạn.', 'xin giấy chứng nhận sinh viên tạm thời ở đâu, thời gian cấp giấy xác nhận là bao lâu, giấy chứng nhận tạm thời, giấy chứng nhận tạm thời là sao', '/dich-vu-sinh-vien'),
(55, 'Văn Phòng Đoàn Thanh Niên', 'Văn phòng Đoàn trường UTH ở đâu? Đăng ký sổ Đoàn, nộp sổ Đoàn ở đâu?', 'Văn phòng Đoàn Thanh niên - Hội Sinh viên UTH đặt tại cơ sở chính Võ Oanh. Đây là nơi quản lý toàn bộ hồ sơ đoàn viên, tiếp nhận sổ Đoàn của sinh viên đầu năm học, xét duyệt các danh hiệu thi đua, cộng điểm rèn luyện và tổ chức các chiến dịch lớn như Mùa hè xanh, Tiếp sức mùa thi.', 'văn phòng đoàn trường uth ở đâu, đăng ký sổ đoàn, nộp sổ đoàn ở đâu, văn phòng đoàn thanh niên, văn phòng đoàn thanh niên là sao', '/thong-tin-truong'),
(56, 'Khảo Sát Ý Kiến Sinh Viên', 'Khảo sát môn học làm ở đâu? Không làm khảo sát giảng viên có bị sao không?', 'Cuối mỗi học kỳ, UTH bắt buộc sinh viên phải tham gia Khảo sát ý kiến về hoạt động giảng dạy của giảng viên trực tuyến trên trang Portal. Sinh viên cố tình không hoàn thành khảo sát đúng hạn sẽ bị tạm khóa chức năng xem điểm thi học kỳ và khóa lịch đăng ký môn học.', 'khảo sát môn học làm ở đâu, không làm khảo sát giảng viên có bị sao không, khảo sát ý kiến sinh viên, khảo sát ý kiến sinh viên là sao', '/thong-tin-ca-nhan'),
(57, 'Đóng Lệ Phí Thi Lại', 'Thi lại có tốn tiền không? Lệ phí thi lại đóng ở đâu?', 'Đối với các môn học bị điểm F, sinh viên áp dụng quy chế học chế tín chỉ của UTH là phải đăng ký học lại và đóng tiền học phí tính theo số tín chỉ môn đó giống như học mới, trường KHÔNG tổ chức kỳ thi lại độc lập thu phí riêng như hệ niên chế cũ.', 'thi lại có tốn tiền không, lệ phí thi lại đóng ở đâu, đóng lệ phí thi lại, đóng lệ phí thi lại là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, lịch thi, hoãn thi, vắng thi, đi thi cần gì', '/cong-thanh-toan'),
(58, 'Thực Tập Tốt Nghiệp', 'Lịch đi thực tập của sinh viên năm cuối? Xin giấy giới thiệu thực tập ở đâu?', 'Sinh viên năm cuối đủ điều kiện sẽ tham gia học phần Thực tập tốt nghiệp. Sinh viên đến văn phòng Khoa/Viện chủ quản để nhận Giấy giới thiệu thực tập nộp cho doanh nghiệp. Sau khi kết thúc, phải nộp lại Báo cáo thực tập có nhận xét và mộc tròn của công ty.', 'lịch đi thực tập của sinh viên năm cuối, xin giấy giới thiệu thực tập ở đâu, thực tập tốt nghiệp, thực tập tốt nghiệp là sao, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/chuong-trinh-khung'),
(59, 'Đồ Án Tốt Nghiệp', 'Điều kiện được làm đồ án ra trường? Điểm GPA bao nhiêu thì được làm khóa luận tốt nghiệp?', 'Điều kiện để sinh viên UTH được giao đề tài làm Đồ án/Khóa luận tốt nghiệp: Tính đến học kỳ xét, sinh viên không bị cảnh báo học vụ; Tích lũy tối thiểu 80% đến 90% số tín chỉ toàn khóa; Điểm trung bình GPA đạt mức quy định riêng của từng Khoa/Viện chuyên ngành.', 'điều kiện được làm đồ án ra trường, điểm gpa bao nhiêu thì được làm khóa luận tốt nghiệp, đồ án tốt nghiệp, đồ án tốt nghiệp là sao, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/chuong-trinh-khung'),
(60, 'Khen Thưởng Sinh Viên', 'Sinh viên xuất sắc được thưởng gì? Tiêu chuẩn xét khen thưởng danh hiệu học tập?', 'Kết thúc mỗi năm học, nhà trường tiến hành xét khen thưởng cho sinh viên đạt danh hiệu Sinh viên Xuất sắc (GPA >= 3.6/4.0) và Sinh viên Giỏi (GPA >= 3.2/4.0) kèm theo điểm rèn luyện loại Tốt trở lên. Sinh viên được tặng giấy khen của Hiệu trưởng và nhận tiền thưởng tương ứng.', 'sinh viên xuất sắc được thưởng gì, tiêu chuẩn xét khen thưởng danh hiệu học tập, khen thưởng sinh viên, khen thưởng sinh viên là sao', '/thong-bao-su-kien'),
(61, 'Mùa Hè Xanh UTH', 'Đăng ký Mùa hè xanh ở đâu? Tiêu chí tuyển chiến sĩ MHX? Đi MHX được bao nhiêu ĐRL?', 'Chiến dịch tình nguyện Mùa Hè Xanh UTH do Đoàn trường tổ chức vào tháng 7 hằng năm. Sinh viên đăng ký qua form chính thức của Đoàn Khoa/Viện. Tiêu chí tuyển chọn dựa trên sức khỏe, đạo đức tốt và tích cực tham gia phong trào. Hoàn thành chiến dịch được cộng tối đa 15-20 điểm rèn luyện.', 'đăng ký mùa hè xanh ở đâu, tiêu chí tuyển chiến sĩ mhx, đi mhx được bao nhiêu đrl, mùa hè xanh uth, mùa hè xanh uth là sao, đrl, điểm rl, chấm drl, cộng điểm rl, khiếu nại drl', '/thong-bao-su-kien'),
(62, 'Tiếp Sức Mùa Thi', 'Đăng ký Tiếp sức mùa thi UTH? Lịch chạy chương trình TSMT?', 'Chương trình Tiếp sức mùa thi diễn ra vào tháng 6 hằng năm nhằm hỗ trợ thí sinh thi THPT Quốc tế. Sinh viên UTH đăng ký tham gia thông qua Hội Sinh viên trường. Chiến sĩ TSMT sẽ trực tại các điểm trường thi để phân luồng giao thông, hỗ trợ nước uống và chỉ đường.', 'đăng ký tiếp sức mùa thi uth, lịch chạy chương trình tsmt, tiếp sức mùa thi, tiếp sức mùa thi là sao', '/thong-bao-su-kien'),
(63, 'Xuân Tình Nguyện', 'Lịch chạy Xuân tình nguyện UTH? Đăng ký đi XTN ở đâu? Chi phí đóng góp XTN?', 'Chiến dịch Xuân Tình Nguyện UTH diễn ra vào dịp cận Tết Nguyên Đán. Các đội hình sẽ thực hiện hoạt động gói bánh chưng, tặng quà cho trẻ em cơ nhỡ, người già neo đơn và dọn dẹp nghĩa trang liệt sĩ. Sinh viên đăng ký qua Fanpage Đoàn - Hội của Khoa/Viện.', 'lịch chạy xuân tình nguyện uth, đăng ký đi xtn ở đâu, chi phí đóng góp xtn, xuân tình nguyện, xuân tình nguyện là sao', '/thong-bao-su-kien'),
(64, 'Giải Chạy Sinh Viên', 'Giải chạy bộ UTH? Đăng ký chạy marathon trường ở đâu? Minh chứng hoàn thành giải chạy?', 'UTH thường xuyên tổ chức hoặc liên kết các giải chạy bộ (Marathon trực tuyến/trực tiếp qua app Strava). Sinh viên hoàn thành cự ly quy định (thường là 21km hoặc 42km tích lũy) sẽ đạt tiêu chí "Thể lực tốt" phục vụ xét danh hiệu Sinh viên 5 Tốt và được cộng ĐRL.', 'giải chạy bộ uth, đăng ký chạy marathon trường ở đâu, minh chứng hoàn thành giải chạy, giải chạy sinh viên, giải chạy sinh viên là sao', '/thong-bao-su-kien'),
(65, 'Ngày Hội Sáng Tạo', 'Cuộc thi ý tưởng sáng tạo UTH? Sáng tạo trẻ sinh viên giao thông?', 'Ngày hội Sáng tạo trẻ UTH là sân chơi khoa học công nghệ, trưng bày các mô hình, phần mềm độc đáo do sinh viên tự nghiên cứu (robot, mô hình cầu đường, app quản lý vận tải). Đề tài đạt giải cao sẽ được hỗ trợ kinh phí tham gia các cuộc thi cấp Thành phố.', 'cuộc thi ý tưởng sáng tạo uth, sáng tạo trẻ sinh viên giao thông, ngày hội sáng tạo, ngày hội sáng tạo là sao', '/thong-bao-su-kien'),
(66, 'Chiến Sĩ Tình Nguyện', 'Danh hiệu Chiến sĩ tình nguyện xuất sắc? Làm sao để được tặng bằng khen MHX?', 'Kết thúc mỗi chiến dịch tình nguyện (MHX, XTN, TSMT), Ban chỉ huy chiến dịch sẽ tổ chức họp xét để tuyên dương các cá nhân có đóng góp xuất sắc. Chiến sĩ đạt danh hiệu sẽ được tặng Giấy khen của Hiệu trưởng hoặc Ủy ban Hội Sinh viên Thành phố.', 'danh hiệu chiến sĩ tình nguyện xuất sắc, làm sao để được tặng bằng khen mhx, chiến sĩ tình nguyện, chiến sĩ tình nguyện là sao', '/thong-bao-su-kien'),
(67, 'Đại Hội Đoàn - Hội', 'Lịch tổ chức Đại hội Đại biểu? Đi bầu cử Đoàn Thanh niên ở đâu?', 'Đại hội Đại biểu Đoàn TNCS Hồ Chí Minh và Đại hội Hội Sinh viên Việt Nam trường UTH được tổ chức định kỳ để bầu ra Ban chấp hành mới. Sinh viên là Đại biểu chính thức sẽ tham gia họp và bỏ phiếu tại Hội trường lớn cơ sở chính Võ Oanh.', 'lịch tổ chức đại hội đại biểu, đi bầu cử đoàn thanh niên ở đâu, đại hội đoàn - hội, đại hội đoàn - hội là sao', '/thong-tin-truong'),
(68, 'Cắm Trại Truyền Thống', 'Hội trại truyền thống UTH học kỳ nào? Địa điểm cắm trại trường? Chi phí hội trại?', 'Hội trại truyền thống UTH thường được tổ chức nhân dịp kỷ niệm ngày thành lập Đoàn 26/03 hoặc ngày truyền thống trường. Địa điểm tổ chức có thể tại sân trường cơ sở Quận 12 hoặc các khu du lịch dã ngoại. Hội trại gồm các hoạt động dựng trại, trò chơi lớn và đêm lửa trại.', 'hội trại truyền thống uth học kỳ nào, địa điểm cắm trại trường, chi phí hội trại, cắm trại truyền thống, cắm trại truyền thống là sao', '/thong-bao-su-kien'),
(69, 'Giải Bóng Đá UTH', 'Giải bóng đá nam/nữ trường UTH? Đăng ký đá banh giải trường ở đâu?', 'Giải bóng đá truyền thống sinh viên UTH tổ chức hằng năm tại sân bóng cỏ nhân tạo. Các đội bóng tham gia tranh tài theo đơn vị lớp hoặc Liên quân Khoa/Viện. Lịch thi đấu và thể lệ được Ban thể thao thuộc Hội sinh viên trường công bố công khai đầu học kỳ 2.', 'giải bóng đá nam/nữ trường uth, đăng ký đá banh giải trường ở đâu, giải bóng đá uth, giải bóng đá uth là sao', '/dang-ky-hoc-phan'),
(70, 'Văn Nghệ Tiếng Hát', 'Cuộc thi tiếng hát sinh viên UTH? Cuộc thi văn nghệ UTH Got Talent?', 'Cuộc thi văn nghệ truyền thống (Tiếng hát sinh viên UTH) là nơi tìm kiếm các tài năng âm nhạc, nhạc cụ, nhảy hiện đại, múa dân gian. Sinh viên đăng ký tiết mục đơn ca, song ca hoặc tốp ca trực tiếp với Đội văn nghệ xung kích của trường để tham gia vòng sơ loại.', 'cuộc thi tiếng hát sinh viên uth, cuộc thi văn nghệ uth got talent, văn nghệ tiếng hát, văn nghệ tiếng hát là sao', '/thong-bao-su-kien'),
(71, 'Chiến Sĩ Đỏ - Hiến Máu', 'Đội tình nguyện hiến máu UTH? Câu lạc bộ Hành Trình Đỏ UTH?', 'Câu lạc bộ Hành Trình Đỏ / Đội Tình nguyện Hiến máu UTH là đơn vị nòng cốt phối hợp với Trung tâm hiến máu nhân đạo TP.HCM để tổ chức các đợt hiến máu tại trường. Thành viên đội sẽ hỗ trợ điều phối, hướng dẫn sinh viên điền form và chăm sóc sinh viên sau hiến máu.', 'đội tình nguyện hiến máu uth, câu lạc bộ hành trình đỏ uth, chiến sĩ đỏ - hiến máu, chiến sĩ đỏ - hiến máu là sao, hiến máu, cộng điểm hiến máu, nghỉ học hiến máu', '/thong-tin-truong'),
(72, 'Minh Chứng ĐRL', 'Nộp minh chứng hoạt động ở đâu? Quên nộp minh chứng có được cộng điểm rèn luyện?', 'Khi tham gia các hoạt động bên ngoài trường (Hiến máu, Tình nguyện hè, Giải chạy), sinh viên phải giữ lại Giấy chứng nhận bản cứng hoặc chụp màn hình kết quả. Sau đó, đăng nhập hệ thống Portal nộp minh chứng đúng thời hạn quy định để Lớp trưởng xét cộng ĐRL.', 'nộp minh chứng hoạt động ở đâu, quên nộp minh chứng có được cộng điểm rèn luyện, minh chứng đrl, minh chứng đrl là sao, đrl, điểm rl, chấm drl, cộng điểm rl, khiếu nại drl', '/thong-tin-ca-nhan'),
(73, 'Điểm Rèn Luyện F', 'Điểm rèn luyện dưới 50 bị phạt thế nào? ĐRL loại Yếu có được tốt nghiệp không?', 'Sinh viên có điểm rèn luyện xếp loại Yếu (dưới 50 điểm) hoặc Kém (dưới 35 điểm) trong một năm học sẽ bị đưa vào danh sách kỷ luật cảnh cáo. Nếu bị xếp loại yếu, kém 2 học kỳ liên tiếp sẽ bị đình chỉ học tập 1 học kỳ; nếu bị lần thứ 3 sẽ bị buộc thôi học.', 'điểm rèn luyện dưới 50 bị phạt thế nào, đrl loại yếu có được tốt nghiệp không, điểm rèn luyện f, điểm rèn luyện f là sao, đrl, điểm rl, chấm drl, cộng điểm rl, khiếu nại drl, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/thong-tin-ca-nhan'),
(74, 'Ngày Hội Việc Làm', 'UTH Job Fair tổ chức khi nào? Sinh viên năm nhất có được tham gia ngày hội việc làm?', 'Ngày hội việc làm UTH Job Fair diễn ra định kỳ hằng năm tại sân trường cơ sở chính. Hoạt động này thu hút hàng chục doanh nghiệp lớn đến phỏng vấn tuyển dụng trực tiếp, nhận hồ sơ thực tập. Tất cả sinh viên các năm đều được tham gia tự do để tìm kiếm cơ hội.', 'uth job fair tổ chức khi nào, sinh viên năm nhất có được tham gia ngày hội việc làm, ngày hội việc làm, ngày hội việc làm là sao', '/thong-bao-su-kien'),
(75, 'Hội Thảo Kỹ Năng', 'Lớp học kỹ năng mềm UTH? Đăng ký chuyên đề kỹ năng ở đâu? Có tính ĐRL không?', 'Phòng Công tác sinh viên phối hợp với các chuyên gia tổ chức các buổi Hội thảo kỹ năng mềm (Kỹ năng viết CV, kỹ năng giao tiếp, quản lý thời gian). Sinh viên quét mã QR điểm danh tại hội trường sẽ được tự động cộng 2-3 điểm rèn luyện vào hệ thống Portal.', 'lớp học kỹ năng mềm uth, đăng ký chuyên đề kỹ năng ở đâu, có tính đrl không, hội thảo kỹ năng, hội thảo kỹ năng là sao, đrl, điểm rl, chấm drl, cộng điểm rl, khiếu nại drl', '/dich-vu-sinh-vien'),
(76, 'Học phí chương trình tiên tiến', 'học phí chương trình tiên tiến, học phí chất lượng cao, học phí CLC, chương trình tiên tiến bao nhiêu tiền', 'UTH hiện gọi chương trình Chất lượng cao trước đây là Chương trình tiên tiến. Mức học phí chương trình tiên tiến áp dụng cho tân sinh viên khóa 2026 là 1.120.000đ/tín chỉ; khóa 2025 áp dụng mức 980.000đ/tín chỉ. Với chương trình đào tạo 120 tín chỉ, tổng học phí trọn khóa khóa 2026 vào khoảng 134 triệu đồng, chưa gồm các khoản phí khác.', 'học phí chương trình tiên tiến, học phí chất lượng cao, học phí clc, chương trình tiên tiến bao nhiêu tiền, học phí chương trình tiên tiến là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, clc bao nhiêu, tiên tiến bao nhiêu 1 chỉ, tiền học clc, học phí cttt', '/cong-thanh-toan'),
(149, 'Lý do học phí chương trình tiên tiến cao hơn', 'vì sao chương trình tiên tiến học phí cao, tại sao CLC đắt hơn đại trà, chương trình tiên tiến khác gì đại trà', 'Học phí chương trình tiên tiến cao hơn chương trình chuẩn do quy mô lớp nhỏ hơn, tăng cường thời lượng tiếng Anh chuyên ngành, cơ sở vật chất hiện đại hơn và có thêm các học phần trải nghiệm hoặc kiến tập tại doanh nghiệp.', 'vì sao chương trình tiên tiến học phí cao, tại sao clc đắt hơn đại trà, chương trình tiên tiến khác gì đại trà, lý do học phí chương trình tiên tiến cao hơn, lý do học phí chương trình tiên tiến cao hơn là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, sao clc mắc, tiên tiến có gì hơn, cttt khác đại trà, đóng nhiều tiền hơn vì sao', '/chuong-trinh-khung'),
(77, 'Quy trình chấm Điểm rèn luyện (ĐRL) hằng kỳ', 'Cách chấm điểm rèn luyện như thế nào? Quy trình họp xét ĐRL của lớp? Khi nào bắt đầu tự đánh giá ĐRL?', 'Quy trình chấm Điểm rèn luyện hằng kỳ tại UTH được thực hiện qua 3 bước bắt buộc: - Sinh viên đăng nhập hệ thống Portal tự đánh giá điểm cá nhân theo các mục quy định. - Tập thể lớp tổ chức họp dưới sự chủ trì của Ban cán sự lớp để thông qua và chấm điểm cho từng sinh viên. - Cố vấn học tập (Giảng viên chủ nhiệm) phê duyệt và gửi danh sách chính thức về Phòng Công tác sinh viên để lưu hệ thống.', 'cách chấm điểm rèn luyện như thế nào, quy trình họp xét đrl của lớp, khi nào bắt đầu tự đánh giá đrl, quy trình chấm điểm rèn luyện (đrl) hằng kỳ, quy trình chấm điểm rèn luyện (đrl) hằng kỳ là sao, đrl, điểm rl, chấm drl, cộng điểm rl, khiếu nại drl', '/thong-tin-ca-nhan'),
(78, 'Thẻ bảo hiểm y tế điện tử (VssID)', 'Xem thẻ bảo hiểm y tế ở đâu? Cách đăng ký tài khoản VssID sinh viên? Mất thẻ bảo hiểm y tế giấy phải làm sao?', 'Nhà trường không cấp thẻ Bảo hiểm y tế (BHYT) bằng giấy vật lý cho sinh viên nữa. Sau khi đóng lệ phí gia hạn BHYT thành công trên cổng thanh toán của trường, sinh viên tải ứng dụng VssID (Bảo hiểm xã hội số) trên điện thoại và đăng ký tài khoản bằng mã số bảo hiểm của mình để sử dụng thẻ BHYT điện tử khi đi khám chữa bệnh tại các bệnh viện.', 'xem thẻ bảo hiểm y tế ở đâu, cách đăng ký tài khoản vssid sinh viên, mất thẻ bảo hiểm y tế giấy phải làm sao, thẻ bảo hiểm y tế điện tử (vssid), thẻ bảo hiểm y tế điện tử (vssid) là sao, bhyt, vssid, bảo hiểm sv, gia hạn bhyt, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/dich-vu-sinh-vien'),
(79, 'Chuẩn tin học quốc tế nâng cao', 'Chứng chỉ tin học IC3 hay MOS tốt hơn? Quy đổi điểm tin học đầu ra như thế nào?', 'UTH công nhận cả hai chứng chỉ quốc tế là MOS và IC3 để xét đạt chuẩn đầu ra Tin học. Đối với chứng chỉ MOS, sinh viên phải đạt từ 3 kỹ năng độc lập trở lên (gồm Word, Excel và Powerpoint). Đối với chứng chỉ IC3, sinh viên phải thi đạt cả 3 phần (Living Online, Key Applications, và Computing Fundamentals). Sinh viên mang chứng chỉ gốc đến Phòng Đào tạo để làm thủ tục hậu kiểm công nhận quy đổi.', 'chứng chỉ tin học ic3 hay mos tốt hơn, quy đổi điểm tin học đầu ra như thế nào, chuẩn tin học quốc tế nâng cao, chuẩn tin học quốc tế nâng cao là sao, mos, ic3, chuẩn tin học, tin học đầu ra', '/dich-vu-sinh-vien'),
(80, 'Quy định sử dụng mạng Wifi nội bộ của trường', 'Cách kết nối wifi trường UTH? Mật khẩu wifi sinh viên là gì? Tại sao không vào được wifi trường?', 'Nhà trường cấp hệ thống mạng Wifi miễn phí tại tất cả các khu vực giảng đường, thư viện và sân trường cho sinh viên. Để kết nối, sinh viên chọn mạng Wifi dành riêng cho người học, sau đó đăng nhập bằng Mã số sinh viên (Username) và Mật khẩu Portal cá nhân của mình. Hệ thống sẽ tự động chặn các truy cập vào trang web độc hại hoặc tải tài liệu lậu dung lượng quá lớn làm nghẽn băng thông.', 'cách kết nối wifi trường uth, mật khẩu wifi sinh viên là gì, tại sao không vào được wifi trường, quy định sử dụng mạng wifi nội bộ của trường, quy định sử dụng mạng wifi nội bộ của trường là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/thong-tin-truong'),
(81, 'Đăng ký tham gia Câu lạc bộ (CLB) đầu năm học', 'Làm sao để vào câu lạc bộ của trường? Ngày hội các câu lạc bộ tổ chức khi nào? Tuyển thành viên CLB UTH?', 'Vào khoảng tháng 9 và tháng 10 hằng năm (đầu học kỳ 1), Hội Sinh viên trường UTH tổ chức Ngày hội các Câu lạc bộ (CLB Festival) tại sân trường cơ sở chính. Tại đây, tất cả các CLB (Học thuật, Nghệ thuật, Thể thao, Tình nguyện) sẽ đặt gian hàng giới thiệu và phát đơn tuyển thành viên mới trực tiếp hoặc trực tuyến qua các trang Fanpage chính thức của mình.', 'làm sao để vào câu lạc bộ của trường, ngày hội các câu lạc bộ tổ chức khi nào, tuyển thành viên clb uth, đăng ký tham gia câu lạc bộ (clb) đầu năm học, đăng ký tham gia câu lạc bộ (clb) đầu năm học là sao', '/thong-bao-su-kien'),
(82, 'Đăng ký cấp lại tài khoản Email sinh viên (@ut.edu.vn)', 'Làm sao để đổi mật khẩu email sinh viên? Bị mất email của trường xử lý thế nào?', 'Email sinh viên định dạng [MSSV]@ut.edu.vn được nhà trường cấp miễn phí cho toàn bộ người học để liên lạc và nhận các thông báo quan trọng. Nếu bị khóa tài khoản hoặc quên mật khẩu email, sinh viên mang Thẻ sinh viên đến trực tiếp văn phòng Trung tâm Dữ liệu và Công nghệ thông tin của trường tại khu nhà chức năng cơ sở chính để được hỗ trợ reset cấp lại mật khẩu ngay trong ngày.', 'làm sao để đổi mật khẩu email sinh viên, bị mất email của trường xử lý thế nào, đăng ký cấp lại tài khoản email sinh viên (@ut.edu.vn), đăng ký cấp lại tài khoản email sinh viên (@ut.edu.vn) là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/thong-tin-ca-nhan'),
(83, 'Hoạt động "Hiến máu tình nguyện" lần 2 trong năm', 'Một năm trường tổ chức hiến máu mấy lần? Lịch hiến máu đợt 2 của trường?', 'Nhằm đáp ứng nhu cầu cung cấp máu cứu người, Đoàn trường và Hội sinh viên UTH phối hợp tổ chức hoạt động hiến máu nhân đạo định kỳ 2 lần trong một năm học (thường rơi vào Học kỳ 1 và Học kỳ 2). Lịch chi tiết của từng đợt sẽ được đăng tải sớm trên trang Portal trước 1 tuần để sinh viên đăng ký tham gia và nhận quyền lợi cộng điểm rèn luyện.', 'một năm trường tổ chức hiến máu mấy lần, lịch hiến máu đợt 2 của trường, hoạt động "hiến máu tình nguyện" lần 2 trong năm, hoạt động "hiến máu tình nguyện" lần 2 trong năm là sao, hiến máu, cộng điểm hiến máu, nghỉ học hiến máu', '/thong-bao-su-kien'),
(84, 'Chế độ miễn giảm học phí cho con em diện chính sách', 'Con thương binh có được giảm học phí không? Thủ tục xin miễn học phí diện hộ nghèo? Nộp hồ sơ giảm học phí ở đâu?', 'Sinh viên thuộc diện con thương binh, bệnh binh, người có công với cách mạng, sinh viên dân tộc thiểu số vùng đặc biệt khó khăn, hoặc sinh viên thuộc hộ nghèo/hộ cận nghèo sẽ được hưởng chính sách miễn hoặc giảm học phí theo đúng quy định của Nhà nước. Sinh viên cần chuẩn bị Sổ hộ nghèo, Giấy chứng nhận diện chính sách bản công chứng nộp về Phòng Công tác sinh viên để xét duyệt đầu năm học.', 'con thương binh có được giảm học phí không, thủ tục xin miễn học phí diện hộ nghèo, nộp hồ sơ giảm học phí ở đâu, chế độ miễn giảm học phí cho con em diện chính sách, chế độ miễn giảm học phí cho con em diện chính sách là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu', '/cong-thanh-toan'),
(85, 'Quy định mượn học cụ, thiết bị tại phòng thí nghiệm', 'Làm sao để mượn đồ phòng thí nghiệm làm đồ án? Quy định mượn thiết bị đo đạc?', 'Sinh viên các ngành kỹ thuật (như Công trình, Điện - Điện tử, CNTT) cần mượn thiết bị, học cụ tại các phòng thí nghiệm, xưởng thực hành để làm đồ án hoặc bài tập lớn phải có Giấy đề xuất mượn thiết bị do Giảng viên hướng dẫn ký duyệt. Sinh viên nộp giấy này cho Cán bộ quản lý phòng thí nghiệm, xuất trình Thẻ sinh viên để ký sổ mượn và có trách nhiệm bảo quản, hoàn trả nguyên vẹn đúng thời hạn.', 'làm sao để mượn đồ phòng thí nghiệm làm đồ án, quy định mượn thiết bị đo đạc, quy định mượn học cụ, thiết bị tại phòng thí nghiệm, quy định mượn học cụ, thiết bị tại phòng thí nghiệm là sao, lịch thi, hoãn thi, vắng thi, đi thi cần gì, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/dich-vu-sinh-vien'),
(86, 'Tiếp nhận hồ sơ Đăng ký xét tuyển Học bạ đợt tiếp theo', 'Khi nào trường nhận hồ sơ học bạ đợt 2? Cách nộp học bạ online vào trường UTH?', 'Hội đồng tuyển sinh UTH tổ chức xét tuyển học bạ THPT thành nhiều đợt trong năm. Thí sinh đăng ký nộp hồ sơ trực tuyến thông qua trang Tuyển sinh chính thức của trường, điền đầy đủ điểm số các môn thuộc tổ hợp xét tuyển và tải ảnh chụp học bạ lên hệ thống. Sau khi có kết quả trúng tuyển tạm thời, thí sinh phải nộp hồ sơ bản giấy về trường để đối chiếu xác thực thông tin.', 'khi nào trường nhận hồ sơ học bạ đợt 2, cách nộp học bạ online vào trường uth, tiếp nhận hồ sơ đăng ký xét tuyển học bạ đợt tiếp theo, tiếp nhận hồ sơ đăng ký xét tuyển học bạ đợt tiếp theo là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không', '/thong-bao-su-kien'),
(87, 'Thủ tục xin tạm hoãn thi học kỳ', 'Bị ốm đột xuất không đi thi được làm sao? Cách xin hoãn thi học kỳ? Đơn xin hoãn thi nộp ở đâu?', 'Nếu gặp lý do bất khả kháng như tai nạn hoặc bệnh tật phải nằm viện điều trị ngay vào ngày thi kết thúc học phần, sinh viên phải làm Đơn xin hoãn thi kèm theo Giấy ra viện hoặc Giấy xác nhận có mộc tròn của bệnh viện nộp về Phòng Đào tạo trong vòng tối đa 3 ngày làm việc kể từ ngày thi của môn đó. Môn học xin hoãn thi thành công sẽ được chuyển điểm sang đợt thi bổ sung hoặc thi ghép cùng khóa sau mà không bị tính điểm 0.', 'bị ốm đột xuất không đi thi được làm sao, cách xin hoãn thi học kỳ, đơn xin hoãn thi nộp ở đâu, thủ tục xin tạm hoãn thi học kỳ, thủ tục xin tạm hoãn thi học kỳ là sao, lịch thi, hoãn thi, vắng thi, đi thi cần gì', '/lich-hoc-trong-tuan'),
(88, 'Quy chế quản lý thông tin và tài sản số của sinh viên', 'Có được chia sẻ tài khoản Portal cho người khác không? Quy định bảo mật thông tin sinh viên UTH?', 'Theo quy định an ninh thông tin của UTH, tài khoản Portal và mật khẩu cá nhân là tài sản số độc quyền của cá nhân sinh viên đó. Sinh viên tuyệt đối không được chia sẻ tài khoản này cho bất kỳ ai khác. Mọi hành vi tự ý chia sẻ tài khoản dẫn đến việc sai lệch dữ liệu đăng ký môn học, kết quả học tập hoặc phát tán thông tin sai sự thật trên hệ thống sẽ bị xử lý kỷ luật nghiêm khắc từ mức cảnh cáo đến đình chỉ học tập.', 'có được chia sẻ tài khoản portal cho người khác không, quy định bảo mật thông tin sinh viên uth, quy chế quản lý thông tin và tài sản số của sinh viên, quy chế quản lý thông tin và tài sản số của sinh viên là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/thong-tin-ca-nhan'),
(89, 'Quy định tham quan kiến tập thực tế tại doanh nghiệp', 'Sinh viên năm mấy được đi kiến tập? Đi kiến tập doanh nghiệp có bắt buộc không?', 'Hoạt động tham quan kiến tập thực tế tại doanh nghiệp, nhà máy, cảng biển là một học phần bắt buộc hoặc hoạt động bổ trợ bổ ích được các Khoa/Viện tổ chức cho sinh viên (thường dành cho sinh viên năm 2 hoặc năm 3). Hoạt động này giúp sinh viên tiếp cận môi trường làm việc thực tế. Sinh viên tham gia phải tuân thủ nghiêm ngặt giờ giấc điều phối của giảng viên trưởng đoàn và mặc đồng phục trường lịch sự.', 'sinh viên năm mấy được đi kiến tập, đi kiến tập doanh nghiệp có bắt buộc không, quy định tham quan kiến tập thực tế tại doanh nghiệp, quy định tham quan kiến tập thực tế tại doanh nghiệp là sao', '/chuong-trinh-khung'),
(90, 'Tư vấn tâm lý và hỗ trợ sinh viên gặp áp lực học đường', 'Trường có phòng tư vấn tâm lý không? Bị stress áp lực học tập thì liên hệ ai hỗ trợ?', 'Nhằm hỗ trợ giải tỏa các áp lực về học tập, cuộc sống hoặc các vấn đề tâm lý cá nhân, UTH có Trung tâm Tư vấn tâm lý sinh viên trực thuộc Phòng Công tác sinh viên. Tại đây, các chuyên gia tâm lý sẽ lắng nghe, chia sẻ và tư vấn định hướng hoàn toàn miễn phí và bảo mật tuyệt đối thông tin cho sinh viên. Sinh viên có thể đặt lịch hẹn tư vấn trực tuyến qua trang hỗ trợ hoặc đến gặp trực tiếp tại văn phòng nhà A.', 'trường có phòng tư vấn tâm lý không, bị stress áp lực học tập thì liên hệ ai hỗ trợ, tư vấn tâm lý và hỗ trợ sinh viên gặp áp lực học đường, tư vấn tâm lý và hỗ trợ sinh viên gặp áp lực học đường là sao', '/dich-vu-sinh-vien'),
(106, 'Rút hồ sơ thôi học', 'rut ho so, thoi hoc, xoa ten, khong hoc nua, xin thoi hoc, nghi hoc luon', 'Sinh viên muốn xin thôi học và rút hồ sơ gốc (Học bạ, Bằng tốt nghiệp THPT) phải làm đơn theo mẫu của trường, xin ý kiến xác nhận không nợ sách Thư viện, không nợ học phí, sau đó nộp về Phòng Đào tạo để ra quyết định xóa tên và trả lại hồ sơ.', 'rut ho so, thoi hoc, xoa ten, khong hoc nua, xin thoi hoc, nghi hoc luon, rút hồ sơ thôi học, rút hồ sơ thôi học là sao', '/dich-vu-sinh-vien'),
(107, 'Đăng ký thi lại chuẩn đầu ra', 'thi lai anh van, thi lai tin hoc, nop don thi lai cdr, dang ky thi tieng anh', 'Trung tâm Ngoại ngữ và Trung tâm Tin học UTH tổ chức các đợt thi đánh giá chuẩn đầu ra định kỳ hằng tháng. Sinh viên theo dõi lịch thông báo, đăng ký và đóng lệ phí dự thi trực tuyến trên trang của Trung tâm trước ngày thi ít nhất 10 ngày.', 'thi lai anh van, thi lai tin hoc, nop don thi lai cdr, dang ky thi tieng anh, đăng ký thi lại chuẩn đầu ra, đăng ký thi lại chuẩn đầu ra là sao, lịch thi, hoãn thi, vắng thi, đi thi cần gì, ielts, toeic, chuẩn anh, miễn anh văn, nộp bằng anh, mos, ic3, chuẩn tin học', '/thong-bao-su-kien'),
(108, 'Xét giảm điểm rèn luyện', 'tru diem ren luyen, khieu nai drl, mo cong drl, cham lai drl, kieu nai drl', 'Nếu phát hiện điểm rèn luyện hiển thị trên Portal bị sai sót hoặc bị trừ điểm không rõ lý do, sinh viên làm đơn khiếu nại gửi Ban cán sự lớp và Cố vấn học tập trong thời gian 5 ngày kể từ khi công bố kết quả dự kiến để được kiểm tra, điều chỉnh.', 'tru diem ren luyen, khieu nai drl, mo cong drl, cham lai drl, kieu nai drl, xét giảm điểm rèn luyện, xét giảm điểm rèn luyện là sao, đrl, điểm rl, chấm drl, cộng điểm rl', '/thong-tin-ca-nhan'),
(109, 'Quy trình vay vốn ngân hàng', 'vay von ngan hang, giay xac nhan vay von, ngan hang chinh sach, don xin vay von', 'Sinh viên thuộc diện đối tượng được vay vốn tín dụng học tập mang hộ khẩu và minh chứng đối tượng đến Phòng Công tác sinh viên để xin cấp "Giấy xác nhận là sinh viên của trường". Sau đó mang giấy này về địa phương để làm thủ tục giải ngân tại Ngân hàng Chính sách Xã hội.', 'vay von ngan hang, giay xac nhan vay von, ngan hang chinh sach, don xin vay von, quy trình vay vốn ngân hàng, quy trình vay vốn ngân hàng là sao', '/dich-vu-sinh-vien'),
(110, 'Chính sách Học bổng tuyển sinh', 'hoc bong tuyen sinh, thu khoa, kien quoc, hoc bong dau vao, khuyen khich dau vao', 'UTH cấp học bổng toàn phần hoặc bán phần (miễn 50% - 100% học phí năm đầu) cho các tân sinh viên đạt danh hiệu Thủ khoa trường, Thủ khoa ngành, hoặc các thí sinh đạt điểm cao xuất sắc trong kỳ thi tốt nghiệp THPT và kỳ thi Đánh giá năng lực.', 'hoc bong tuyen sinh, thu khoa, kien quoc, hoc bong dau vao, khuyen khich dau vao, chính sách học bổng tuyển sinh, chính sách học bổng tuyển sinh là sao, hb, xin học bổng, săn hb, được học bổng không, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không', '/thong-bao-su-kien'),
(111, 'Thời gian giữ xe tối đa tại trường', 'gui xe qua dem, mat xe, quen lay xe, giu xe may, bai xe mo cua den may gio', 'Bãi giữ xe trường UTH mở cửa từ 6h00 đến 22h00 hằng ngày. Sinh viên không được để xe lại bãi qua đêm. Trường hợp xe bị hư hỏng bắt buộc phải để lại, sinh viên phải báo cáo và đăng ký thông tin với Đội bảo vệ trực ban của trường để được quản lý.', 'gui xe qua dem, mat xe, quen lay xe, giu xe may, bai xe mo cua den may gio, thời gian giữ xe tối đa tại trường, thời gian giữ xe tối đa tại trường là sao', '/thong-tin-truong'),
(112, 'Thủ tục phúc khảo điểm quá trình', 'phuc khao diem thanh phan, xem lai diem giua ky, diem qua trinh bi sai, sửa điểm', 'Điểm quá trình (điểm chuyên cần, bài tập, giữa kỳ) do Giảng viên bộ môn quản lý và công bố trên lớp. Nếu có thắc mắc, sinh viên phải phản hồi trực tiếp với Giảng viên trước khi môn học kết thúc. Khi điểm đã nộp về trường, giảng viên mới không thể tự ý chỉnh sửa.', 'phuc khao diem thanh phan, xem lai diem giua ky, diem qua trinh bi sai, sửa điểm, thủ tục phúc khảo điểm quá trình, thủ tục phúc khảo điểm quá trình là sao, coi điểm, điểm f, rớt môn, gpa, phúc khảo', '/ket-qua-hoc-tap'),
(113, 'Tham gia hiến máu có được nghỉ học', 'hien mau co duoc nghi, xin nghi hoc hien mau, hoãn hoc hien mau', 'Sinh viên tham gia ngày hội hiến máu tình nguyện tổ chức tại trường sẽ được hỗ trợ cấp Giấy chứng nhận hiến máu. Giấy này được dùng làm minh chứng hợp lệ để xin phép nghỉ học có lý do đối với các tiết học diễn ra trong ngày hiến máu đó.', 'hien mau co duoc nghi, xin nghi hoc hien mau, hoãn hoc hien mau, tham gia hiến máu có được nghỉ học, tham gia hiến máu có được nghỉ học là sao, hiến máu, cộng điểm hiến máu, nghỉ học hiến máu', '/lich-hoc-trong-tuan'),
(114, 'Đổi thẻ nhựa sang thẻ sinh viên', 'doi the nhua, lam the sinh vien moi, chip the sinh vien, tich hop the ngan hang', 'Hiện nay UTH triển khai cấp thẻ sinh viên tích hợp thẻ ngân hàng thông minh. Sinh viên năm nhất nhận thẻ theo lịch phân phối của phòng CTSV. Sinh viên khóa cũ có nhu cầu đổi phôi thẻ lỗi sang thẻ đa năng mới đăng ký và đóng phí tại văn phòng phòng CTSV.', 'doi the nhua, lam the sinh vien moi, chip the sinh vien, tich hop the ngan hang, đổi thẻ nhựa sang thẻ sinh viên, đổi thẻ nhựa sang thẻ sinh viên là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/dich-vu-sinh-vien'),
(115, 'Hủy tư cách đoàn viên', 'xoa ten doan, rut so doan, khong sinh hoat doan, dong doan phi', 'Đoàn viên không tham gia sinh hoạt Đoàn hoặc không đóng đoàn phí liên tục trong 3 tháng mà không có lý do chính đáng sẽ bị xem xét xóa tên khỏi danh sách Đoàn viên và thông báo về Chi đoàn lớp sinh hoạt để trừ điểm rèn luyện theo quy chế.', 'xoa ten doan, rut so doan, khong sinh hoat doan, dong doan phi, hủy tư cách đoàn viên, hủy tư cách đoàn viên là sao', '/thong-tin-ca-nhan'),
(116, 'Chính sách hỗ trợ bảo hiểm tai nạn', 'bao hiem tai nan, bhtn, bi tai nan duoc den bao nhieu, ho tro nam vien', 'Ngoài BHYT bắt buộc, nhà trường có liên kết đơn vị bảo hiểm để sinh viên đăng ký tự nguyện Bảo hiểm tai nạn. Khi xảy ra sự cố chấn thương, nằm viện, sinh viên mang Giấy ra viện và hóa đơn chi phí đến Phòng Công tác sinh viên để làm thủ tục nhận tiền bảo hiểm bồi thường.', 'bao hiem tai nan, bhtn, bi tai nan duoc den bao nhieu, ho tro nam vien, chính sách hỗ trợ bảo hiểm tai nạn, chính sách hỗ trợ bảo hiểm tai nạn là sao, bhyt, vssid, bảo hiểm sv, gia hạn bhyt', '/dich-vu-sinh-vien'),
(117, 'Mượn thiết bị âm thanh, sự kiện', 'muon loa keo, loa mic, thiet bi su kien, loa mic clb, thiet bi doan hoi', 'Các Câu lạc bộ, Chi đoàn lớp cần mượn loa kéo, micro, thiết bị âm thanh hoặc backdrop để tổ chức hoạt động phong trào phải làm đơn đăng ký thông qua Văn phòng Đoàn trường hoặc Phòng Quản trị thiết bị trước ngày diễn ra sự kiện ít nhất 3 ngày.', 'muon loa keo, loa mic, thiet bi su kien, loa mic clb, thiet bi doan hoi, mượn thiết bị âm thanh, sự kiện, mượn thiết bị âm thanh, sự kiện là sao', '/dich-vu-sinh-vien'),
(118, 'Cấp lại giấy chứng nhận quốc phòng', 'mat bang quan su, mat giay quoc phong, cap lai chung chi gdqp, xin bang diem gdqp', 'Chứng chỉ Giáo dục Quốc phòng - An ninh do Trung tâm GDQP cấp gốc 1 lần duy nhất. Nếu bị mất, sinh viên không được cấp lại bằng gốc mà phải làm đơn xin cấp Giấy xác nhận hoàn thành môn học hoặc bản sao bảng điểm trực tiếp tại Trung tâm quản lý để nộp xét tốt nghiệp.', 'mat bang quan su, mat giay quoc phong, cap lai chung chi gdqp, xin bang diem gdqp, cấp lại giấy chứng nhận quốc phòng, cấp lại giấy chứng nhận quốc phòng là sao, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm', '/dich-vu-sinh-vien'),
(119, 'Đăng ký tham gia hiến máu đợt hè', 'hien mau mua he, hien mau hk he, lich hien mau thang 6 thang 7', 'Hoạt động hiến máu tình nguyện đợt hè thường được phối hợp tổ chức vào khoảng tháng 6 hoặc tháng 7 nhằm bổ sung nguồn máu dự trữ khan hiếm. Sinh viên học kỳ hè hoặc sinh viên ở lại thành phố đăng ký trực tuyến qua Fanpage Hội Sinh viên trường UTH.', 'hien mau mua he, hien mau hk he, lich hien mau thang 6 thang 7, đăng ký tham gia hiến máu đợt hè, đăng ký tham gia hiến máu đợt hè là sao, hiến máu, cộng điểm hiến máu, nghỉ học hiến máu', '/thong-bao-su-kien'),
(120, 'Quy định số lần cảnh báo học vụ', 'bi canh bao may lan thi bi duoi, gioi han canh bao, canh bao hoc vu muc do 2', 'Theo quy chế học vụ UTH, sinh viên bị cảnh báo học vụ 2 lần liên tiếp sẽ bị buộc thôi học. Nếu bị cảnh báo rải rác không liên tiếp, sinh viên vẫn được tiếp tục học nhưng phải chủ động gặp Cố vấn học tập để làm cam kết lộ trình cải thiện điểm số.', 'bi canh bao may lan thi bi duoi, gioi han canh bao, canh bao hoc vu muc do 2, quy định số lần cảnh báo học vụ, quy định số lần cảnh báo học vụ là sao', '/thong-tin-ca-nhan'),
(121, 'Thời hạn sử dụng của thẻ thư viện', 'gia han the thu vien, the thu vien het han, khoa the thu vien', 'Thẻ thư viện UTH (tích hợp trên Thẻ sinh viên) có giá trị sử dụng xuyên suốt toàn bộ khóa học chính quy của sinh viên tại trường. Tài khoản thư viện sẽ tự động bị khóa sau khi sinh viên nhận quyết định tốt nghiệp hoặc quyết định thôi học, ngừng học.', 'gia han the thu vien, the thu vien het han, khoa the thu vien, thời hạn sử dụng của thẻ thư viện, thời hạn sử dụng của thẻ thư viện là sao, mất tài khoản, quên mật khẩu, portal lỗi, thẻ sv, email trường', '/dich-vu-sinh-vien'),
(122, 'Thủ tục xin miễn học thể dục', 'mien hoc the duc, khong hoc the duc bi khuyet tat, don mien giao duc the chat, gay chan, chan thuong, tai nan, dau om', 'Sinh viên có khuyết tật, dị tật hoặc mắc các bệnh lý mãn tính không thể tham gia vận động mạnh phải làm đơn xin miễn/giảm học phần Giáo dục thể chất kèm theo Bệnh án, Giấy chứng nhận thương tật của bệnh viện cấp Quận trở lên nộp về Bộ môn GDTC để xét duyệt chuyển đổi môn học phù hợp.', 'mien hoc the duc, khong hoc the duc bi khuyet tat, don mien giao duc the chat, gay chan, chan thuong, tai nan, dau om, thủ tục xin miễn học thể dục, thủ tục xin miễn học thể dục là sao', '/dang-ky-hoc-phan'),
(123, 'Thời gian nhận bằng tốt nghiệp', 'khi nao nhan bang goc, lay bang tot nghiep o dau, phat bang tot nghiep', 'Bằng tốt nghiệp chính thức được cấp phát cho sinh viên trong vòng 30 ngày kể từ ngày ký Quyết định công nhận tốt nghiệp. Sinh viên nhận bằng trực tiếp tại lễ tốt nghiệp hoặc đến văn phòng Phòng Đào tạo để ký sổ nhận bằng gốc (mang theo CCCD).', 'khi nao nhan bang goc, lay bang tot nghiep o dau, phat bang tot nghiep, thời gian nhận bằng tốt nghiệp, thời gian nhận bằng tốt nghiệp là sao, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/thong-bao-su-kien'),
(124, 'Phí phạt nợ học phí quá hạn', 'nop tre hoc phi, nop phat hoc phi, tre han dong tien hoc bi phat bao nhieu', 'UTH không áp dụng hình thức phạt tiền mặt khi sinh viên nộp học phí trễ hạn. Tuy nhiên, sinh viên không hoàn thành học phí đúng thời gian quy định sẽ bị hệ thống tự động khóa tài khoản Portal, hủy danh sách đăng ký học phần và cấm tham gia kỳ thi học kỳ.', 'nop tre hoc phi, nop phat hoc phi, tre han dong tien hoc bi phat bao nhieu, phí phạt nợ học phí quá hạn, phí phạt nợ học phí quá hạn là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu', '/cong-thanh-toan'),
(125, 'Xin hoãn đi thực tập tốt nghiệp', 'hoan thuc tap, don xin hoan thuc tap nam cuoi, doi lich di thuc tap', 'Sinh viên năm cuối vì lý do sức khỏe hoặc chưa tích lũy đủ các môn học điều kiện bắt buộc muốn xin hoãn học phần Thực tập tốt nghiệp phải làm đơn xin hoãn nộp về Văn phòng Khoa/Viện chủ quản trước khi danh sách phân công đơn vị thực tập được công bố.', 'hoan thuc tap, don xin hoan thuc tap nam cuoi, doi lich di thuc tap, xin hoãn đi thực tập tốt nghiệp, xin hoãn đi thực tập tốt nghiệp là sao, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/chuong-trinh-khung'),
(126, 'Chính sách hỗ trợ sinh viên nghèo', 'tro cap kho khan, ho tro sinh vien ngheo đột xuất, tro cap xa hoi', 'Sinh viên gặp tai nạn, thiên tai, hỏa hoạn hoặc gia đình gặp biến cố lớn đột xuất dẫn đến hoàn cảnh đặc biệt khó khăn làm đơn xin hỗ trợ gửi Phòng Công tác sinh viên. Nhà trường sẽ xem xét trích Quỹ hỗ trợ sinh viên để cấp kinh phí trợ cấp đột xuất.', 'tro cap kho khan, ho tro sinh vien ngheo đột xuất, tro cap xa hoi, chính sách hỗ trợ sinh viên nghèo, chính sách hỗ trợ sinh viên nghèo là sao', '/dich-vu-sinh-vien'),
(127, 'Đồ án tốt nghiệp đạt điểm F xử lý sao', 'rot do an tot nghiep, lam lai khoa luan, rot khoa luan ra truong', 'Sinh viên bảo vệ Đồ án hoặc Khóa luận tốt nghiệp nhận điểm F (không đạt) sẽ không được tốt nghiệp đúng hạn. Sinh viên bắt buộc phải đăng ký làm lại đề tài mới hoặc đăng ký lại học phần đồ án vào kỳ xét duyệt tiếp theo của năm học sau và đóng phí theo quy định.', 'rot do an tot nghiep, lam lai khoa luan, rot khoa luan ra truong, đồ án tốt nghiệp đạt điểm f xử lý sao, đồ án tốt nghiệp đạt điểm f xử lý sao là sao, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm, ra trường, xét tốt nghiệp, lấy bằng, nợ môn ra trường', '/chuong-trinh-khung'),
(128, 'Quy chế xét học bổng khi nợ môn', 'no mon co duoc hoc bong, rot mon co duoc xet hoc bong, thi lai co duoc hoc bong', 'Theo quy chế khen thưởng của UTH, sinh viên chỉ cần nợ 1 môn học (nhận điểm F) hoặc đăng ký thi lại/học lại bất kỳ môn nào trong học kỳ đó thì sẽ lập tức bị tước quyền tham gia xét duyệt Học bổng khuyến khích học tập, bất kể điểm GPA tổng của bạn cao bao nhiêu.', 'no mon co duoc hoc bong, rot mon co duoc xet hoc bong, thi lai co duoc hoc bong, quy chế xét học bổng khi nợ môn, quy chế xét học bổng khi nợ môn là sao, coi điểm, điểm f, rớt môn, gpa, phúc khảo, sửa điểm, lịch thi, hoãn thi, vắng thi, đi thi cần gì, hb, xin học bổng, săn hb', '/thong-bao-su-kien'),
(129, 'Liên hệ Ban quản lý ký túc xá', 'so dien thoai ban quan ly ktx, gap ai de phan anh ktx, ban quan ly noi tru', 'Để phản ánh các vấn đề về điện nước, an ninh phòng ở hoặc nộp chi phí nội trú Ký túc xá, sinh viên đến trực tiếp văn phòng Ban quản lý nội trú Ký túc xá đặt tại khu vực cổng vào của khu nội trú cơ sở đó để được cán bộ trực ban giải quyết.', 'so dien thoai ban quan ly ktx, gap ai de phan anh ktx, ban quan ly noi tru, liên hệ ban quản lý ký túc xá, liên hệ ban quản lý ký túc xá là sao, ktx, ở ktx, phòng ktx, nội trú, ký túc xá', '/thong-tin-truong'),
(131, 'Xét tuyển thẳng UTH năm 2026', 'xét tuyển thẳng UTH 2026, tuyển thẳng UTH, điều kiện xét tuyển thẳng, đề án riêng UTH', 'Năm 2026, UTH có phương thức xét tuyển thẳng theo quy định của Bộ GD&ĐT và theo Đề án riêng của trường. Nhóm có thể đăng ký gồm thí sinh đạt giải HSG cấp Tỉnh/Thành trở lên, có chứng chỉ tiếng Anh quốc tế từ IELTS 6.0 hoặc tương đương, học sinh trường chuyên/trọng điểm, đạt học lực Giỏi nhiều học kỳ, thuộc nhóm ngành ưu tiên nhà nước hoặc có thư giới thiệu từ doanh nghiệp đối tác của UTH.', 'xét tuyển thẳng uth 2026, tuyển thẳng uth, điều kiện xét tuyển thẳng, đề án riêng uth, xét tuyển thẳng uth năm 2026, xét tuyển thẳng uth năm 2026 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, tuyển thẳng sao, ielts có tuyển thẳng không, hsg tỉnh được tuyển thẳng không, đề án riêng là gì', '/thong-bao-su-kien'),
(150, 'Xét tuyển kết hợp UTH năm 2026', 'xét tuyển kết hợp UTH 2026, công thức UTH120, xét học bạ 2026, xét điểm THPT 2026, đánh giá năng lực UTH', 'Phương thức chủ đạo năm 2026 của UTH là xét tuyển kết hợp theo công thức riêng của trường (UTH120). Công thức này có thể kết hợp điểm thi Đánh giá năng lực, điểm học bạ cả năm lớp 12, điểm thi tốt nghiệp THPT năm 2026, điểm ưu tiên và điểm khuyến khích theo quy định.', 'xét tuyển kết hợp uth 2026, công thức uth120, xét học bạ 2026, xét điểm thpt 2026, đánh giá năng lực uth, xét tuyển kết hợp uth năm 2026, xét tuyển kết hợp uth năm 2026 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, uth120, xét tuyển kiểu gì, học bạ có tính không, điểm thpt tính sao, dgnl có cộng không', '/thong-bao-su-kien'),
(151, 'UTH còn xét học bạ hoặc điểm thi riêng lẻ không', 'UTH còn xét học bạ riêng không, UTH còn xét điểm thi THPT riêng không, xét tuyển riêng lẻ UTH', 'Từ năm 2025, UTH không còn xét tuyển riêng lẻ theo điểm thi THPT hoặc học bạ như các năm trước. Các loại điểm này chỉ là thành phần trong công thức xét tuyển kết hợp chung của trường.', 'uth còn xét học bạ riêng không, uth còn xét điểm thi thpt riêng không, xét tuyển riêng lẻ uth, uth còn xét học bạ hoặc điểm thi riêng lẻ không, uth còn xét học bạ hoặc điểm thi riêng lẻ không là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, còn xét học bạ không, chỉ lấy điểm thi được không, học bạ riêng lẻ, thpt riêng lẻ', '/thong-bao-su-kien'),
(152, 'Thời lượng chương trình đào tạo UTH', 'chương trình UTH bao nhiêu tín chỉ, học UTH mấy năm, UTH 120 tín chỉ', 'Chương trình đào tạo đại học của UTH được thiết kế 120 tín chỉ, thời gian học tối thiểu khoảng 3 năm nếu sinh viên học đúng tiến độ và đáp ứng điều kiện tích lũy của chương trình.', 'chương trình uth bao nhiêu tín chỉ, học uth mấy năm, uth 120 tín chỉ, thời lượng chương trình đào tạo uth, thời lượng chương trình đào tạo uth là sao, học mấy năm, 120 tín là sao, bao lâu ra trường, học nhanh được không', '/chuong-trinh-khung'),
(132, 'Tổ hợp môn xét tuyển phổ biến tại UTH', 'tổ hợp môn xét tuyển UTH, khối thi vào UTH, A00 A01 D01 D07, UTH xét khối nào', 'Các tổ hợp phổ biến nhiều năm qua tại UTH gồm A00 (Toán - Lý - Hóa), A01 (Toán - Lý - Anh), D01 (Toán - Văn - Anh) và D07 (Toán - Hóa - Anh). Thí sinh cần kiểm tra tổ hợp được phép xét theo từng mã ngành trong Đề án tuyển sinh chính thức.', 'tổ hợp môn xét tuyển uth, khối thi vào uth, a00 a01 d01 d07, uth xét khối nào, tổ hợp môn xét tuyển phổ biến tại uth, tổ hợp môn xét tuyển phổ biến tại uth là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, uth xét khối gì, a00 có được không, a01 vào ngành nào, d01 d07, chọn tổ hợp nào', '/chuong-trinh-khung'),
(153, 'Cách dùng tổ hợp trong xét tuyển kết hợp UTH', 'công thức xét tuyển tổ hợp môn UTH, điểm tổ hợp UTH, xét tuyển kết hợp theo tổ hợp', 'Trong phương thức xét tuyển kết hợp, điểm xét tuyển được tính từ 3 môn theo tổ hợp đăng ký rồi tổng hợp cùng điểm học bạ, điểm thi THPT và điểm thi Đánh giá năng lực nếu có. Công thức và trọng số có thể thay đổi theo từng ngành và từng năm.', 'công thức xét tuyển tổ hợp môn uth, điểm tổ hợp uth, xét tuyển kết hợp theo tổ hợp, cách dùng tổ hợp trong xét tuyển kết hợp uth, cách dùng tổ hợp trong xét tuyển kết hợp uth là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, điểm tổ hợp tính sao, công thức tổ hợp, học bạ cộng thpt kiểu gì, trọng số xét tuyển', '/thong-bao-su-kien'),
(154, 'Ngành cạnh tranh cao tại UTH', 'ngành cạnh tranh cao UTH, ngành hot UTH, CNTT Logistics UTH', 'Công nghệ thông tin và Logistics - Quản lý chuỗi cung ứng thường là các nhóm ngành có chỉ tiêu lớn và mức độ cạnh tranh cao tại UTH. Thí sinh nên tra cứu điểm chuẩn, chỉ tiêu và tổ hợp xét tuyển mới nhất trước khi đặt nguyện vọng.', 'ngành cạnh tranh cao uth, ngành hot uth, cntt logistics uth, ngành cạnh tranh cao tại uth, ngành cạnh tranh cao tại uth là sao, ngành hot, cntt có khó không, logistics khó đậu không, ngành nào cạnh tranh', '/chuong-trinh-khung'),
(133, 'Điểm chuẩn CNTT UTH năm 2025', 'điểm chuẩn CNTT UTH 2025, điểm chuẩn công nghệ thông tin 2025, ngành CNTT UTH bao nhiêu điểm', 'Năm 2025, điểm chuẩn trúng tuyển nhóm Công nghệ thông tin UTH theo phương thức xét tuyển kết hợp như sau: CNTT chương trình tiên tiến 800 điểm; Khoa học dữ liệu và AI chương trình tiên tiến 800 điểm; CNTT chương trình hoàn toàn bằng tiếng Anh 800 điểm; Truyền thông số và Đổi mới sáng tạo 720 điểm; Smart Logistics 720 điểm; Công nghệ ô tô số 800 điểm.', 'điểm chuẩn cntt uth 2025, điểm chuẩn công nghệ thông tin 2025, ngành cntt uth bao nhiêu điểm, điểm chuẩn cntt uth năm 2025, điểm chuẩn cntt uth năm 2025 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, cntt lấy bao nhiêu, điểm cntt 2025, ai dữ liệu bao nhiêu, smart logistics cntt', '/chuong-trinh-khung'),
(155, 'Lưu ý thang điểm chuẩn CNTT UTH năm 2025', 'thang điểm chuẩn CNTT UTH 2025, điểm chuẩn UTH có phải thang 30 không, xét tuyển kết hợp CNTT', 'Mức điểm chuẩn CNTT năm 2025 của UTH được tính theo thang điểm riêng của phương thức xét tuyển kết hợp, dao động trong khoảng 668-999 điểm tùy ngành. Điểm này không thể so sánh trực tiếp với điểm chuẩn thang 30 của các trường xét điểm thi THPT truyền thống.', 'thang điểm chuẩn cntt uth 2025, điểm chuẩn uth có phải thang 30 không, xét tuyển kết hợp cntt, lưu ý thang điểm chuẩn cntt uth năm 2025, lưu ý thang điểm chuẩn cntt uth năm 2025 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, sao điểm 800, có phải thang 30 không, điểm chuẩn lạ, 800 điểm là gì', '/chuong-trinh-khung'),
(134, 'Điểm chuẩn ngành Logistics và Quản lý chuỗi cung ứng năm 2025', 'điểm chuẩn logistics 2025, diem chuan logistics 2025, nganh logistics lay bao nhieu diem, diem xet tuyen logistics', 'Logistics và Quản lý chuỗi cung ứng tiếp tục là một trong những ngành có điểm chuẩn cao nhất UTH. Theo điểm chuẩn chính thức công bố ngày 22/8/2025 (phương thức Xét tuyển kết hợp, thang điểm riêng của trường, KHÔNG phải thang 30): Logistics và Quản lý chuỗi cung ứng - chương trình tiên tiến: 963 điểm (chỉ xếp sau ngành Khoa học dữ liệu - chương trình tiên tiến với 999 điểm, cao nhất toàn trường); Logistics và Quản lý chuỗi cung ứng - chương trình hoàn toàn bằng tiếng Anh: 720 điểm. Đây tiếp tục là ngành có mức độ cạnh tranh rất cao tại UTH trong nhiều năm liền.', 'điểm chuẩn logistics 2025, nganh logistics lay bao nhieu diem, diem xet tuyen logistics, điểm chuẩn ngành logistics và quản lý chuỗi cung ứng năm 2025, điểm chuẩn ngành logistics và quản lý chuỗi cung ứng năm 2025 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không', '/chuong-trinh-khung'),
