(157, 'Nhóm ngành điểm chuẩn 720-800 UTH năm 2025', 'ngành điểm chuẩn 720 800 UTH, điểm chuẩn CNTT ngôn ngữ anh quản trị kinh doanh', 'Nhóm ngành phổ biến ở mức 720-800 điểm năm 2025 gồm Công nghệ thông tin, Ngôn ngữ Anh, Luật, Quản trị kinh doanh, Hệ thống thông tin quản lý, Kỹ thuật cơ khí, Kỹ thuật ô tô, Kinh tế xây dựng, Khai thác vận tải và Kinh tế vận tải, đa số thuộc chương trình tiên tiến.', 'ngành điểm chuẩn 720 800 uth, điểm chuẩn cntt ngôn ngữ anh quản trị kinh doanh, nhóm ngành điểm chuẩn 720-800 uth năm 2025, nhóm ngành điểm chuẩn 720-800 uth năm 2025 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, 720 800 là ngành nào, điểm trung bình, ngành tầm 800, ngành dễ hơn top', '/chuong-trinh-khung'),
(158, 'Nhóm ngành điểm chuẩn thấp nhất UTH năm 2025', 'ngành điểm chuẩn thấp UTH 2025, ngành 668 điểm UTH, điểm sàn thấp nhất UTH', 'Nhóm có điểm chuẩn thấp nhất năm 2025 ở mức 668 điểm gồm các chương trình chuẩn như Kỹ thuật tàu thủy, Kỹ thuật xây dựng công trình thủy, Khoa học hàng hải và một số ngành liên quan đường sắt tốc độ cao.', 'ngành điểm chuẩn thấp uth 2025, ngành 668 điểm uth, điểm sàn thấp nhất uth, nhóm ngành điểm chuẩn thấp nhất uth năm 2025, nhóm ngành điểm chuẩn thấp nhất uth năm 2025 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, ngành thấp điểm, 668 là ngành nào, dễ đậu hơn, điểm thấp nhất', '/chuong-trinh-khung'),
(159, 'Lưu ý khi đọc điểm chuẩn UTH năm 2025', 'điểm chuẩn UTH có phải thang 30 không, thang điểm xét tuyển kết hợp UTH, tra cứu điểm chuẩn đầy đủ', 'Điểm chuẩn UTH năm 2025 tính theo công thức riêng của phương thức xét tuyển kết hợp, gồm điểm học bạ lớp 12, điểm thi THPT, điểm Đánh giá năng lực và điểm ưu tiên. Vì vậy, mức điểm này không so sánh trực tiếp với thang 30 truyền thống. Thí sinh nên tra cứu bảng điểm chuẩn đầy đủ theo từng mã ngành tại tuyensinh.ut.edu.vn.', 'điểm chuẩn uth có phải thang 30 không, thang điểm xét tuyển kết hợp uth, tra cứu điểm chuẩn đầy đủ, lưu ý khi đọc điểm chuẩn uth năm 2025, lưu ý khi đọc điểm chuẩn uth năm 2025 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, điểm 999 là sao, không phải thang 30, coi bảng đầy đủ ở đâu, công thức riêng', '/thong-bao-su-kien'),
(136, 'Chỉ tiêu tuyển sinh UTH năm 2026', 'chỉ tiêu tuyển sinh 2026, UTH tuyển bao nhiêu sinh viên, chỉ tiêu ngành CNTT 2026', 'UTH công bố Đề án tuyển sinh đại học chính quy năm 2026 vào ngày 16/6/2026. Chỉ tiêu được phân bổ chi tiết theo từng mã ngành trong Đề án tuyển sinh chính thức, không nên hiểu là một con số tổng cố định cho mọi ngành.', 'chỉ tiêu tuyển sinh 2026, uth tuyển bao nhiêu sinh viên, chỉ tiêu ngành cntt 2026, chỉ tiêu tuyển sinh uth năm 2026, chỉ tiêu tuyển sinh uth năm 2026 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, chỉ tiêu bao nhiêu, uth tuyển mấy người, cntt tuyển bao nhiêu, xem chỉ tiêu ở đâu', '/thong-tin-truong'),
(160, 'Chuyên ngành mới trong tuyển sinh UTH năm 2026', 'chuyên ngành mới UTH 2026, ngành mới UTH, blockchain AI smart logistics UAV', 'Năm 2026, UTH mở rộng nhiều chuyên ngành gắn với công nghệ số như Khoa học dữ liệu - Blockchain và AI, Smart Logistics, Công nghệ ô tô số, Kinh tế số và Trí tuệ nhân tạo, Truyền thông số và Đổi mới sáng tạo, Logistics xanh và phát triển bền vững, Quản lý và công nghệ UAV.', 'chuyên ngành mới uth 2026, ngành mới uth, blockchain ai smart logistics uav, chuyên ngành mới trong tuyển sinh uth năm 2026, chuyên ngành mới trong tuyển sinh uth năm 2026 là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, ngành mới, blockchain ai, uav là ngành gì, smart logistics, công nghệ ô tô số', '/chuong-trinh-khung'),
(137, 'IELTS dùng để xét tuyển thẳng UTH', 'IELTS xét tuyển UTH, IELTS tuyển thẳng UTH, TOEIC TOEFL xét tuyển UTH', 'UTH không áp dụng bảng quy đổi IELTS sang điểm xét tuyển cố định. Trong xét tuyển đầu vào, thí sinh có IELTS từ 6.0 trở lên hoặc chứng chỉ tương đương như TOEFL iBT từ 60, TOEFL ITP từ 530, TOEIC từ 600, Bậc 4/6 trở lên và còn hiệu lực có thể dùng làm tiêu chí đăng ký diện xét tuyển thẳng theo Đề án riêng của UTH.', 'ielts xét tuyển uth, ielts tuyển thẳng uth, toeic toefl xét tuyển uth, ielts dùng để xét tuyển thẳng uth, ielts dùng để xét tuyển thẳng uth là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, ielts, toeic, chuẩn anh, miễn anh văn, nộp bằng anh, ielts 6.0 được gì, toeic 600 có xét được không, ielts có cộng điểm không', '/thong-bao-su-kien'),
(161, 'IELTS dùng để miễn học phần tiếng Anh sau nhập học', 'IELTS miễn học tiếng Anh UTH, nộp IELTS để miễn Anh văn, miễn học phí tiếng Anh bằng IELTS', 'Sau khi nhập học, sinh viên có thể nộp chứng chỉ IELTS hoặc chứng chỉ ngoại ngữ tương đương để trường xét miễn các cấp độ học phần tiếng Anh phù hợp với năng lực. Cấp độ được miễn thì sinh viên được miễn học phí của cấp độ đó. Hồ sơ nộp trực tuyến qua support.ut.edu.vn ở mục Phòng Đào tạo/Chuẩn đào tạo ngoại ngữ UTH.', 'ielts miễn học tiếng anh uth, nộp ielts để miễn anh văn, miễn học phí tiếng anh bằng ielts, ielts dùng để miễn học phần tiếng anh sau nhập học, ielts dùng để miễn học phần tiếng anh sau nhập học là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, ielts, toeic, chuẩn anh, miễn anh văn, nộp bằng anh, nộp ielts ở đâu, khỏi học tiếng anh', '/dich-vu-sinh-vien'),
(138, 'Điểm sàn xét tuyển UTH hiện nay', 'điểm sàn UTH, ngưỡng đảm bảo chất lượng UTH, điểm sàn nhận hồ sơ UTH', 'Từ năm 2025, UTH chuyển sang phương thức xét tuyển kết hợp làm phương thức chủ đạo nên khái niệm điểm sàn theo thang 30 truyền thống không còn áp dụng thống nhất cho toàn trường như trước. Ngưỡng đầu vào được quy định theo điều kiện xét tuyển kết hợp và theo từng ngành trong Đề án tuyển sinh.', 'điểm sàn uth, ngưỡng đảm bảo chất lượng uth, điểm sàn nhận hồ sơ uth, điểm sàn xét tuyển uth hiện nay, điểm sàn xét tuyển uth hiện nay là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, điểm sàn bao nhiêu, bao nhiêu điểm nộp được, thang 30 còn không, ngưỡng đầu vào', '/thong-bao-su-kien'),
(162, 'Điều kiện điểm Toán tối thiểu khi xét tuyển UTH', 'điểm Toán tối thiểu UTH, Toán 5 điểm có xét UTH được không, điều kiện xét tuyển kết hợp UTH', 'Điều kiện đầu vào tối thiểu của phương thức xét tuyển kết hợp hiện nay là thí sinh phải có điểm thi môn Toán trong kỳ thi tốt nghiệp THPT từ 5.0 trở lên. Một số ngành có thể yêu cầu cao hơn, ví dụ ngành Toán ứng dụng yêu cầu từ 6.0. Thí sinh cần kiểm tra Đề án tuyển sinh chính thức mới nhất tại tuyensinh.ut.edu.vn.', 'điểm toán tối thiểu uth, toán 5 điểm có xét uth được không, điều kiện xét tuyển kết hợp uth, điều kiện điểm toán tối thiểu khi xét tuyển uth, điều kiện điểm toán tối thiểu khi xét tuyển uth là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không, toán 5 được không, toán dưới 5 có xét được không, điều kiện toán, toán ứng dụng cần mấy điểm', '/thong-bao-su-kien'),
(139, 'Đăng ký nguyện vọng vào UTH trên hệ thống của Bộ GD&ĐT', 'đăng ký nguyện vọng, dang ky nguyen vong, ma truong uth la gi, xep nguyen vong vao uth', 'Để xét tuyển vào UTH bằng điểm thi THPT, thí sinh phải đăng ký nguyện vọng trên hệ thống chung của Bộ GD&ĐT theo đúng lịch quy định. Thí sinh cần nhập chính xác Mã trường của UTH là GTS và chọn đúng mã ngành, mã tổ hợp môn mong muốn. Nên xếp ngành yêu thích nhất ở Nguyện vọng 1.', 'đăng ký nguyện vọng, ma truong uth la gi, xep nguyen vong vao uth, đăng ký nguyện vọng vào uth trên hệ thống của bộ gd&đt, đăng ký nguyện vọng vào uth trên hệ thống của bộ gd&đt là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không', '/thong-bao-su-kien'),
(140, 'Lệ phí xét tuyển hồ sơ đầu vào', 'lệ phí xét tuyển, le phi xet tuyen, nop tien xet hoc ba bao nhieu, dong tien nguyen vong', 'Lệ phí xét tuyển đối với phương thức xét học bạ nộp trực tiếp về trường UTH áp dụng theo quy định hành chính thu chi. Đối với phương thức xét điểm thi THPT, thí sinh đóng lệ phí trực tuyến trực tiếp trên hệ thống cổng thông tin của Bộ GD&ĐT khi tiến hành xác nhận số lượng nguyện vọng.', 'lệ phí xét tuyển, nop tien xet hoc ba bao nhieu, dong tien nguyen vong, lệ phí xét tuyển hồ sơ đầu vào, lệ phí xét tuyển hồ sơ đầu vào là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không', '/cong-thanh-toan'),
(141, 'Thời gian công bố kết quả trúng tuyển chính thức', 'khi nào biết kết quả trúng tuyển, khi nao biet ket qua trung tuyen, lich cong bo diem chuan uth', 'Thời gian công bố điểm chuẩn và danh sách trúng tuyển chính thức của UTH tuân thủ nghiêm ngặt theo lộ trình chung của Bộ GD&ĐT (thường vào khoảng tháng 8 hằng năm). Kết quả xét tuyển sớm bằng học bạ thường được trường thông báo trước đó vào tháng 6 hoặc tháng 7.', 'khi nào biết kết quả trúng tuyển, lich cong bo diem chuan uth, thời gian công bố kết quả trúng tuyển chính thức, thời gian công bố kết quả trúng tuyển chính thức là sao, tuyển sinh, xét tuyển, điểm chuẩn, nguyện vọng, đậu không', '/thong-bao-su-kien'),
(142, 'Thủ tục xác nhận nhập học trực tuyến', 'xác nhận nhập học, xac nhan nhap hoc online, huong dan nhap hoc uth, khong xac nhan nhap hoc bi gi', 'Sau khi có thông báo trúng tuyển chính thức, thí sinh bắt buộc phải thực hiện bước Xác nhận nhập học trực tuyến trên hệ thống của Bộ GD&ĐT trước thời hạn quy định. Thí sinh cố tình không xác nhận nhập học đúng hạn sẽ bị hệ thống tự động hủy kết quả trúng tuyển vào trường.', 'xác nhận nhập học, xac nhan nhap hoc online, huong dan nhap hoc uth, khong xac nhan nhap hoc bi gi, thủ tục xác nhận nhập học trực tuyến, thủ tục xác nhận nhập học trực tuyến là sao', '/dich-vu-sinh-vien'),
(143, 'Hồ sơ bản giấy cần chuẩn bị khi đến trường làm thủ tục nhập học', 'hồ sơ nhập học cần gì, ho so nhap hoc can gi, mang theo gi khi nhap hoc uth, giay to nhap hoc', 'Hồ sơ nhập học bản giấy nộp tại trường bao gồm: Giấy báo trúng tuyển bản gốc; Học bạ THPT (bản sao công chứng); Giấy chứng nhận tốt nghiệp tạm thời hoặc Bằng tốt nghiệp THPT; Bản sao CCCD; Giấy khai sinh; và các giấy tờ minh chứng đối tượng ưu tiên chính sách (nếu có).', 'hồ sơ nhập học cần gì, mang theo gi khi nhap hoc uth, giay to nhap hoc, hồ sơ bản giấy cần chuẩn bị khi đến trường làm thủ tục nhập học, hồ sơ bản giấy cần chuẩn bị khi đến trường làm thủ tục nhập học là sao', '/dich-vu-sinh-vien'),
(144, 'Quy trình làm thủ tục nhập học trực tiếp tại trường', 'quy trình nhập học trực tiếp, quy trinh nhap hoc truc tiep, den truong nhap hoc o dau, huong dan tan sinh vien', 'Khi đến nhập học trực tiếp tại cơ sở chính của UTH, tân sinh viên thực hiện theo quy trình luồng: - Tra cứu số thứ tự và phòng làm thủ tục tại sảnh hướng dẫn. - Nộp hồ sơ bản giấy tại bàn tiếp nhận của Khoa/Viện. - Đóng học phí và các khoản bảo hiểm bắt buộc tại bàn tài chính. - Nhận lịch học Tuần sinh hoạt công dân và chụp ảnh làm Thẻ sinh viên.', 'quy trình nhập học trực tiếp, den truong nhap hoc o dau, huong dan tan sinh vien, quy trình làm thủ tục nhập học trực tiếp tại trường, quy trình làm thủ tục nhập học trực tiếp tại trường là sao', '/thong-tin-truong'),
(145, 'Chính sách rút hồ sơ hoàn học phí đối với tân sinh viên', 'rút học phí nhập học, rut hoc phi nhap hoc, nhap hoc roi xin rut lai tien, thoi hoc rut lai hoc phi', 'Tân sinh viên đã làm thủ tục nhập học nhưng vì lý do cá nhân muốn xin rút hồ sơ không theo học nữa sẽ được xem xét hoàn trả học phí tùy theo thời điểm nộp đơn. Nếu nộp đơn rút trước ngày khai giảng chính thức, sinh viên được hoàn lại một phần học phí theo quy định đóng rút bồi hoàn của nhà trường; sau ngày khai giảng sẽ không được hoàn phí.', 'rút học phí nhập học, nhap hoc roi xin rut lai tien, thoi hoc rut lai hoc phi, chính sách rút hồ sơ hoàn học phí đối với tân sinh viên, chính sách rút hồ sơ hoàn học phí đối với tân sinh viên là sao, hp, tiền học, đóng hp, nợ học phí, công nợ, đóng tiền ở đâu', '/cong-thanh-toan');
INSERT INTO `tickets` (`student_name`, `mssv`, `title`, `content`, `status`, `admin_reply`, `created_at`) VALUES
('Phạm Anh Tuấn', '075205019210', 'Hỗ trợ về: Học phí hệ chất lượng cao...', 'Cho em hỏi học phí chất lượng cao học kỳ hè tính như thế nào ạ? Có giống học kỳ chính không?', 'pending', NULL, NOW() - INTERVAL 2 HOUR),
('Phạm Anh Tuấn', '075205019210', 'Hỗ trợ về: Cách tính điểm rèn luyện...', 'Thưa thầy cô, em tham gia hiến máu tình nguyện thì được cộng bao nhiêu điểm rèn luyện và nộp minh chứng ở đâu ạ?', 'replied', 'Chào em, hiến máu tình nguyện được cộng 5 điểm rèn luyện. Em nộp minh chứng trực tuyến trên Portal sinh viên nhé.', NOW() - INTERVAL 1 DAY);
